// GENERADO por backend/herramientas/generar_aprende.py a partir de backend/retos/conceptos/bd.py. No lo edites a mano: cambia los conceptos y vuelve a generarlo.
// m = etapa · t = título · x = qué es · u = para qué sirve · p = puntos clave · c = código · h = qué hace · r = ahora tú · e = error común
export default [
  {"m": "Qué es una base de datos", "t": "Datos e información", "x": "Los datos son hechos sueltos y la información son datos con sentido.\n\n«Ana», «20» y «Lima» son datos sueltos. Cuando los juntas (Ana tiene 20 años y vive en Lima) se vuelven información útil. Una base de datos guarda datos de forma ordenada para poder convertirlos en información cuando los consultas.", "u": "Entender por qué se guardan datos y cómo se convierten en información.\n\nTienes los valores sueltos «Ana», «20» y «Lima» y quieres saber cómo llamar a cada uno.", "p": ["Un dato es un valor suelto, como un nombre o un número.", "La información son datos organizados que tienen sentido.", "Una base de datos guarda datos para obtener información."], "c": "-- Tres datos sueltos\n-- 'Ana'   20   'Lima'\n-- Juntos y con sentido son información:\nSELECT 'Ana' AS nombre, 20 AS edad, 'Lima' AS ciudad;", "h": "Junta tres datos sueltos en una fila con sentido.", "r": "Reto mental: Los valores sueltos como «Ana» o «20» se llaman ___. (5 letras)", "e": "Confundir un dato suelto con información completa."},
  {"m": "Qué es una base de datos", "t": "Base de datos", "x": "Conjunto organizado de datos guardados para consultarlos.\n\nUna base de datos es como un archivador digital muy bien organizado: guarda datos de usuarios, productos o pedidos y permite encontrarlos al instante. Casi toda aplicación web, de móvil o de juegos guarda su información en una.", "u": "Guardar mucha información de forma ordenada y segura.\n\nQuieres guardar los datos de miles de clientes de una tienda de forma ordenada para buscarlos al instante.", "p": ["Una base de datos guarda información de forma organizada.", "Casi todas las aplicaciones usan una base de datos.", "Permite encontrar datos muy rápido."], "c": "-- Una base de datos agrupa varias tablas\nCREATE DATABASE tienda;\nUSE tienda;\n-- dentro irán las tablas: clientes, productos, pedidos...", "h": "Crea una base de datos llamada tienda y la selecciona.", "r": "Reto mental: Un conjunto organizado de datos guardados es una ___ de datos. (4 letras)", "e": "Guardar toda la información en archivos sueltos sin orden."},
  {"m": "Qué es una base de datos", "t": "Para qué sirve una base de datos", "x": "Herramienta para almacenar, consultar y proteger información.\n\nCuando entras a una red social, el sistema consulta tu perfil, tus amigos y tus mensajes en una base de datos. Sirve para guardar sin perder, buscar rápido, compartir entre muchos usuarios y mantener los datos seguros y consistentes.", "u": "Que muchas personas usen los mismos datos a la vez.\n\nQuieres que miles de usuarios consulten y modifiquen la misma información a la vez sin perderla.", "p": ["Una base de datos permite buscar información rápidamente.", "Varias personas pueden usar los mismos datos a la vez.", "Protege los datos contra pérdidas y accesos no permitidos."], "c": "-- Ejemplo de uso real: buscar el perfil de un usuario\nSELECT nombre, correo\nFROM usuarios\nWHERE id = 42;", "h": "Busca el nombre y el correo de un usuario concreto.", "r": "Reto mental: Una base de datos permite que muchos ___ usen los mismos datos. (una palabra)", "e": "Usar un archivo de texto para datos que cambian constantemente."},
  {"m": "Qué es una base de datos", "t": "Sistema gestor SGBD", "x": "Programa que crea, administra y protege las bases de datos.\n\nEl SGBD (o DBMS en inglés) es el programa intermediario: recibe tus peticiones, guarda y lee los datos del disco y controla quién puede acceder. MySQL, PostgreSQL y SQL Server son ejemplos. Tú nunca tocas los archivos directamente.", "u": "Gestionar los datos sin manipular archivos a mano.\n\nNecesitas el programa que recibe tus consultas, lee el disco y controla los permisos.", "p": ["El SGBD administra las bases de datos.", "MySQL y PostgreSQL son sistemas gestores.", "Las aplicaciones hablan con el SGBD, no con los archivos."], "c": "-- Le pides cosas al SGBD con SQL; él se encarga del resto\nSHOW DATABASES;      -- lista las bases que gestiona\nSELECT VERSION();    -- consulta qué gestor y versión es", "h": "Pregunta al gestor qué bases tiene y qué versión es.", "r": "Reto mental: Las siglas de sistema gestor de bases de datos son ___. (4 letras)", "e": "Creer que MySQL es la base de datos y no el gestor."},
  {"m": "Qué es una base de datos", "t": "Base de datos relacional", "x": "Base de datos que guarda los datos en tablas relacionadas.\n\nEn el modelo relacional, la información está en tablas con filas y columnas, y las tablas se conectan mediante valores comunes (claves). Es el modelo más usado desde los años 70 y su lenguaje es SQL.", "u": "Organizar datos con estructura clara y conexiones entre ellos.\n\nQuieres guardar clientes y pedidos en tablas conectadas entre sí.", "p": ["Una base relacional guarda datos en tablas.", "Las tablas de una base relacional se conectan entre sí.", "El lenguaje de las bases relacionales es SQL."], "c": "-- Dos tablas conectadas: cada pedido apunta a un cliente\n-- clientes(id, nombre)\n-- pedidos(id, cliente_id, total)\nSELECT c.nombre, p.total\nFROM clientes c\nJOIN pedidos p ON p.cliente_id = c.id;", "h": "Une la tabla de clientes con la de pedidos mediante un valor común.", "r": "Reto mental: Una base que guarda datos en tablas conectadas es una base ___. (10 letras)", "e": "Guardar toda la información en una única tabla gigante."},
  {"m": "Qué es una base de datos", "t": "Tabla", "x": "Estructura de filas y columnas que guarda un tipo de datos.\n\nUna tabla representa un tipo de cosa: usuarios, productos, pedidos. Sus columnas definen qué datos se guardan de cada cosa (nombre, precio) y sus filas son cada elemento concreto. Una base de datos suele tener muchas tablas.", "u": "Agrupar datos del mismo tema, como clientes o productos.\n\nQuieres un espacio de la base de datos para todos los productos de tu tienda.", "p": ["Una tabla guarda datos del mismo tema.", "Una tabla tiene columnas y filas.", "Una base de datos puede tener muchas tablas."], "c": "-- Una tabla para los productos\nCREATE TABLE productos (\n  id INT,\n  nombre VARCHAR(50),\n  precio DECIMAL(8,2)\n);", "h": "Define una tabla de productos con id, nombre y precio.", "r": "Reto mental: Una tabla está formada por filas y ___. (8 letras)", "e": "Mezclar datos de temas distintos en la misma tabla."},
  {"m": "Qué es una base de datos", "t": "Fila o registro", "x": "Cada elemento concreto guardado en una tabla.\n\nCada fila de la tabla productos es un producto distinto: la fila 1 puede ser «Café», la fila 2 «Té». También se llama registro o tupla. Cada fila tiene un valor en cada columna.", "u": "Representar un cliente, un producto o un pedido en particular.\n\nQuieres hablar de un producto concreto, por ejemplo el café, dentro de la tabla.", "p": ["Una fila (o registro) representa un elemento concreto.", "Cada fila tiene un valor por cada columna.", "Insertar datos significa añadir filas."], "c": "-- Cada INSERT añade UNA fila (un registro)\nINSERT INTO productos VALUES (1, 'Café', 4.50);\nINSERT INTO productos VALUES (2, 'Té',   3.20);", "h": "Añade dos filas, una por cada producto.", "r": "Reto mental: Otro nombre de «fila» en una tabla es ___. (8 letras)", "e": "Confundir una fila con una columna."},
  {"m": "Qué es una base de datos", "t": "Columna o campo", "x": "Característica que se guarda de cada elemento de la tabla.\n\nLas columnas son los datos que se guardan de cada cosa: id, nombre, precio. Cada columna tiene un nombre y un tipo de dato (número, texto, fecha). Todas las filas comparten las mismas columnas.", "u": "Definir qué datos tiene cada registro.\n\nQuieres hablar del dato «precio» que tienen todos los productos.", "p": ["Una columna (o campo) define un tipo de dato de la tabla.", "Todas las filas comparten las mismas columnas.", "Cada columna tiene un nombre y un tipo de dato."], "c": "-- Cada línea dentro del paréntesis es una columna\nCREATE TABLE clientes (\n  id      INT,           -- columna de números\n  nombre  VARCHAR(40),   -- columna de texto\n  alta    DATE           -- columna de fechas\n);", "h": "Define tres columnas con distintos tipos de dato.", "r": "Reto mental: Otro nombre de «columna» en una tabla es ___. (5 letras)", "e": "Añadir una columna distinta en cada fila."},
  {"m": "Qué es una base de datos", "t": "Clave primaria", "x": "Columna que identifica de forma única cada fila.\n\nEl id es la clave primaria típica: no se repite ni puede estar vacío. Gracias a ella puedes decir «el cliente 7» sin dudas, aunque haya dos personas llamadas Ana. Cada tabla debería tener una.", "u": "Distinguir un registro de todos los demás.\n\nHay dos clientes llamados Ana y quieres distinguirlos con un valor único.", "p": ["La clave primaria identifica cada fila de forma única.", "La clave primaria no puede repetirse ni estar vacía.", "Cada tabla debería tener una clave primaria."], "c": "CREATE TABLE clientes (\n  id INT PRIMARY KEY,      -- clave primaria: única y obligatoria\n  nombre VARCHAR(40)\n);\nINSERT INTO clientes VALUES (1, 'Ana');\nINSERT INTO clientes VALUES (2, 'Ana');   -- mismo nombre, distinto id", "h": "Distingue a dos clientes con el mismo nombre gracias a su clave primaria.", "r": "Reto mental: La columna que identifica cada fila se llama clave ___. (8 letras)", "e": "Usar el nombre como clave primaria. El id 1 ya existe: una clave primaria no puede repetirse."},
  {"m": "Qué es una base de datos", "t": "CRUD", "x": "Las cuatro operaciones básicas sobre los datos.\n\nCRUD son las siglas de Create (crear), Read (leer), Update (actualizar) y Delete (borrar). En SQL equivalen a INSERT, SELECT, UPDATE y DELETE. Casi todo lo que hace una app, desde registrar un usuario hasta borrar una foto, es una de estas cuatro.", "u": "Describir todo lo que una aplicación hace con la información.\n\nQuieres nombrar las cuatro operaciones básicas: crear, leer, actualizar y borrar datos.", "p": ["CRUD significa crear, leer, actualizar y borrar.", "INSERT crea, SELECT lee, UPDATE actualiza y DELETE borra.", "Casi toda aplicación se reduce a operaciones CRUD."], "c": "INSERT INTO tareas VALUES (1, 'Estudiar');     -- Create\nSELECT * FROM tareas;                          -- Read\nUPDATE tareas SET titulo = 'Repasar' WHERE id = 1;  -- Update\nDELETE FROM tareas WHERE id = 1;               -- Delete", "h": "Recorre crear, leer, actualizar y borrar sobre una tabla de tareas.", "r": "Reto mental: La R de CRUD significa ___ (leer en inglés). (4 letras)", "e": "Olvidar la cláusula WHERE al actualizar o borrar."},
  {"m": "Qué es una base de datos", "t": "SQL", "x": "Lenguaje estándar para hablar con las bases de datos relacionales.\n\nSQL significa Structured Query Language (lenguaje de consulta estructurado). Se parece al inglés: SELECT nombre FROM clientes. Con pocas palabras clave y mucha práctica puedes consultar millones de filas. Sirve en MySQL, PostgreSQL, SQL Server y muchos más.", "u": "Pedir, añadir, modificar y borrar datos.\n\nQuieres un lenguaje con el que pedir datos a una base relacional con frases casi en inglés.", "p": ["SQL significa Structured Query Language.", "SQL sirve para consultar y modificar bases relacionales.", "SQL se parece al inglés en su forma de escribirse."], "c": "-- SQL se lee casi como inglés\nSELECT nombre, edad     -- qué quiero ver\nFROM alumnos            -- de qué tabla\nWHERE edad >= 18;       -- con qué condición", "h": "Pide el nombre y la edad de los alumnos mayores de edad.", "r": "Reto mental: SQL significa Structured ___ Language. (5 letras)", "e": "Creer que SQL es un lenguaje de programación general."},
  {"m": "Qué es una base de datos", "t": "Cliente y servidor de BD", "x": "Modelo donde una aplicación pide datos a un servidor de bases de datos.\n\nLa base de datos vive en un servidor y las aplicaciones (clientes) se conectan por la red con usuario y contraseña. Así, muchas apps comparten la misma información y puedes mejorar el servidor sin tocar las aplicaciones. Cada conexión necesita servidor, puerto, usuario y contraseña.", "u": "Separar la aplicación de la base que guarda los datos.\n\nTu aplicación está en un ordenador y los datos en otro, al que se conecta por la red.", "p": ["Las aplicaciones se conectan al servidor de la base de datos.", "Para conectarse hace falta servidor, puerto, usuario y contraseña.", "Muchas aplicaciones pueden usar la misma base."], "c": "-- Datos que necesita una conexión (ejemplo ilustrativo)\n-- servidor:   127.0.0.1\n-- puerto:     3306\n-- usuario:    root\n-- base:       tienda\nSELECT 'conectado' AS estado;", "h": "Lista los datos necesarios para conectarse y confirma la conexión.", "r": "Reto mental: El puerto habitual de MySQL es ___. (4 números)", "e": "Guardar la contraseña de la base dentro del código visible."},
  {"m": "Qué es una base de datos", "t": "MySQL", "x": "Gestor de bases de datos relacionales gratuito y muy popular.\n\nMySQL se creó en 1995 y hoy lo usan WordPress, Facebook (en parte) y millones de sitios. MariaDB es una alternativa casi idéntica. Es gratuito, rápido y se instala fácil, por eso es ideal para aprender.", "u": "Alojar los datos de sitios web y aplicaciones.\n\nBuscas un gestor gratuito, rápido y fácil de instalar para aprender SQL.", "p": ["MySQL es un gestor de bases de datos relacionales.", "MySQL es gratuito y muy popular.", "MariaDB es una alternativa casi idéntica a MySQL."], "c": "-- Comandos habituales de MySQL\nSHOW DATABASES;          -- ver las bases\nCREATE DATABASE escuela; -- crear una base\nUSE escuela;             -- elegirla\nSHOW TABLES;             -- ver sus tablas", "h": "Muestra, crea y selecciona bases de datos en MySQL.", "r": "Reto mental: Una alternativa casi idéntica a MySQL es ___. (7 letras)", "e": "Confundir MySQL con el lenguaje SQL."},
  {"m": "Qué es una base de datos", "t": "XAMPP y Workbench", "x": "Paquete que instala MySQL y herramienta visual para gestionarlo.\n\nXAMPP instala en tu ordenador Apache, PHP y MySQL con un solo clic. MySQL Workbench es el programa gráfico donde escribes SQL, ves las tablas y diseñas esquemas. Primero enciendes MySQL en XAMPP y luego te conectas desde Workbench.", "u": "Tener un servidor de bases de datos en tu propio ordenador.\n\nQuieres un servidor MySQL en tu propio ordenador y un programa visual para manejarlo.", "p": ["XAMPP instala un servidor MySQL en tu ordenador.", "Workbench es una herramienta visual para trabajar con MySQL.", "Hay que encender MySQL en XAMPP antes de conectarse."], "c": "-- 1) Abre XAMPP y pulsa Start junto a MySQL\n-- 2) Abre MySQL Workbench y conéctate a 127.0.0.1\n-- 3) Prueba que todo funciona:\nSELECT 'Hola, MySQL' AS saludo;", "h": "Confirma que la conexión con el servidor local funciona.", "r": "Reto mental: El programa visual para trabajar con MySQL se llama MySQL ___. (9 letras)", "e": "Intentar conectarse sin encender el servidor MySQL."},
  {"m": "Qué es una base de datos", "t": "Bases de datos NoSQL", "x": "Bases que no usan tablas y se adaptan a datos flexibles.\n\nNoSQL agrupa varios tipos: documentos (MongoDB), clave-valor (Redis), columnas (Cassandra) y grafos (Neo4j). Son útiles cuando los datos cambian mucho de forma o se necesita muchísima velocidad. No sustituyen a las relacionales: se eligen según el caso.", "u": "Guardar datos sin estructura fija o con enormes volúmenes.\n\nTus datos cambian de forma constantemente y no encajan en tablas fijas.", "p": ["NoSQL agrupa bases de datos que no usan tablas relacionales.", "MongoDB guarda documentos y Redis guarda pares clave-valor.", "NoSQL no sustituye a las bases relacionales."], "c": "-- Un documento NoSQL (MongoDB) se parece a un objeto JSON:\n-- { \"nombre\": \"Ana\", \"intereses\": [\"web\", \"datos\"], \"edad\": 20 }\n-- Cada documento puede tener campos distintos\nSELECT 'ejemplo conceptual' AS nota;", "h": "Muestra cómo se vería un documento flexible de una base NoSQL.", "r": "Reto mental: MongoDB es una base de datos de ___. (10 letras: documentos)", "e": "Usar NoSQL por moda sin necesitarlo."},
  {"m": "Qué es una base de datos", "t": "Hoja de cálculo y base de datos", "x": "Comparación entre guardar datos en Excel o en una base.\n\nUna hoja de cálculo es excelente para pocos datos y un solo usuario. Cuando hay miles de filas, varias personas editando a la vez, relaciones entre tablas y exigencias de seguridad, necesitas una base de datos. Una base valida datos y evita duplicados con reglas.", "u": "Elegir la herramienta adecuada para cada volumen de datos.\n\nTu hoja de cálculo ya tiene 200 000 filas y diez personas la editan a la vez.", "p": ["Una hoja de cálculo sirve bien para pocos datos y un usuario.", "Una base de datos soporta muchos usuarios y muchísimos datos.", "Una base de datos permite reglas para evitar datos erróneos."], "c": "-- Una base de datos puede impedir datos duplicados\nCREATE TABLE socios (\n  dni VARCHAR(9) PRIMARY KEY,   -- dos socios no pueden tener el mismo dni\n  nombre VARCHAR(40) NOT NULL   -- el nombre no puede quedar vacío\n);", "h": "Impone reglas que una hoja de cálculo no puede garantizar.", "r": "Reto mental: Para pocos datos y un solo usuario basta una hoja de ___. (7 letras)", "e": "Usar una hoja de cálculo para una aplicación con muchos usuarios."},
  {"m": "Qué es una base de datos", "t": "Seguridad de los datos", "x": "Medidas que protegen la información de accesos no permitidos.\n\nIncluye contraseñas fuertes, usuarios con permisos mínimos, conexiones cifradas y no guardar contraseñas en texto plano. La aplicación nunca debe usar el usuario administrador. Una filtración de datos puede dañar a muchas personas.", "u": "Evitar robos, filtraciones y cambios indebidos.\n\nQuieres que una aplicación solo pueda leer datos y no borrarlos.", "p": ["Cada usuario de la base debe tener solo los permisos necesarios.", "Las contraseñas de los usuarios nunca deben guardarse en texto plano.", "Las conexiones deben cifrarse cuando viajan por la red."], "c": "-- Principio de mínimos permisos: la app solo puede leer y añadir\nCREATE USER 'app'@'localhost' IDENTIFIED BY 'una-clave-larga';\nGRANT SELECT, INSERT ON tienda.* TO 'app'@'localhost';\n-- (no se le da DELETE ni DROP)", "h": "Crea un usuario que solo puede consultar e insertar, no borrar.", "r": "Reto mental: Cada usuario debe tener solo los permisos ___. (10 letras: necesarios)", "e": "Usar el usuario administrador (root) en la aplicación."},
  {"m": "Qué es una base de datos", "t": "Copias de seguridad", "x": "Copias de los datos que permiten recuperarlos si algo falla.\n\nLos discos fallan, las personas se equivocan y existen virus que cifran datos. Una copia de seguridad (backup) guardada en otro lugar te permite recuperarlo todo. Se programan automáticamente y se comprueba de vez en cuando que se pueden restaurar.", "u": "No perder información por errores, fallos o ataques.\n\nUn error borra una tabla entera y quieres recuperarla tal como estaba ayer.", "p": ["Una copia de seguridad permite recuperar los datos tras un fallo.", "La copia debe guardarse en un lugar distinto al original.", "Conviene comprobar que la copia realmente se puede restaurar."], "c": "-- Copia de seguridad desde la terminal (no es SQL):\n--   mysqldump -u root -p tienda > copia_tienda.sql\n-- Restaurarla:\n--   mysql -u root -p tienda < copia_tienda.sql\nSELECT 'haz copias y pruébalas' AS consejo;", "h": "Muestra cómo copiar y restaurar una base con mysqldump.", "r": "Reto mental: En inglés, una copia de seguridad se llama ___. (6 letras)", "e": "Hacer copias pero no comprobar nunca que se pueden restaurar."},
  {"m": "Qué es una base de datos", "t": "Integridad de los datos", "x": "Garantía de que los datos son correctos y coherentes.\n\nLa base de datos puede imponer reglas: campos obligatorios (NOT NULL), valores únicos (UNIQUE), claves primarias y relaciones válidas (claves foráneas). Así un pedido no puede apuntar a un cliente que no existe y un correo no se registra dos veces.", "u": "Evitar datos incompletos, duplicados o contradictorios.\n\nQuieres impedir que dos usuarios se registren con el mismo correo.", "p": ["La integridad evita datos incorrectos o contradictorios.", "NOT NULL obliga a que un campo tenga valor.", "UNIQUE impide valores repetidos."], "c": "CREATE TABLE usuarios (\n  id INT PRIMARY KEY,\n  correo VARCHAR(80) NOT NULL UNIQUE,   -- obligatorio y sin repetir\n  edad INT CHECK (edad >= 0)            -- no admite edades negativas\n);", "h": "Impone correo obligatorio y único, y edad no negativa.", "r": "Reto mental: La restricción que impide valores repetidos es ___. (6 letras)", "e": "Confiar en que la aplicación valida todo y no poner reglas en la base."},
  {"m": "Qué es una base de datos", "t": "Cómo practicar bases de datos", "x": "Hábito de crear tablas y consultas propias a diario.\n\nCrea una base pequeña sobre algo que te guste (tus películas, una tienda, un torneo) y hazte preguntas: ¿cuántas?, ¿cuáles son las más caras? Responde con SQL. Practicar con tus propias preguntas fija mucho mejor que copiar ejemplos.", "u": "Aprender SQL escribiendo consultas reales.\n\nQuieres aprender SQL de forma entretenida usando tus propios datos.", "p": ["Practicar con datos que te interesan ayuda a aprender SQL.", "Hacerse preguntas y responderlas con consultas es un buen método.", "Practicar un poco cada día funciona mejor que mucho de golpe."], "c": "-- Reto: crea tu mini base de películas y respóndele preguntas\nCREATE TABLE peliculas (id INT PRIMARY KEY, titulo VARCHAR(60), anio INT);\nINSERT INTO peliculas VALUES (1, 'Coco', 2017), (2, 'Soul', 2020);\nSELECT titulo FROM peliculas WHERE anio > 2018;", "h": "Crea una pequeña tabla de películas y pregunta cuáles son posteriores a 2018.", "r": "Reto mental: SQL se aprende practicando con tus propias ___. (9 letras: consultas)", "e": "Leer sobre SQL sin escribir nunca una consulta."},
  {"m": "Modelado de datos", "t": "Entidad", "x": "Cosa del mundo real sobre la que se guardan datos.\n\nAntes de crear tablas se piensa en las entidades: en una escuela serán alumno, curso y profesor. Cada entidad suele convertirse en una tabla. Un buen modelo empieza identificando bien las entidades.", "u": "Decidir qué tablas necesita una base de datos.\n\nEstás diseñando la base de una escuela y piensas en alumno, curso y profesor.", "p": ["Una entidad es algo sobre lo que se guarda información.", "Cada entidad suele convertirse en una tabla.", "El modelado empieza identificando las entidades."], "c": "-- Cada entidad se convierte en una tabla\nCREATE TABLE alumnos    (id INT PRIMARY KEY, nombre VARCHAR(40));\nCREATE TABLE cursos     (id INT PRIMARY KEY, titulo VARCHAR(40));\nCREATE TABLE profesores (id INT PRIMARY KEY, nombre VARCHAR(40));", "h": "Crea una tabla por cada entidad de una escuela.", "r": "Reto mental: En una escuela, «alumno» o «curso» son ___. (9 letras)", "e": "Meter varias entidades distintas en la misma tabla."},
  {"m": "Modelado de datos", "t": "Atributo", "x": "Característica que describe a una entidad.\n\nLos atributos del alumno pueden ser nombre, fecha de nacimiento y correo. Cada atributo se convierte en una columna. Conviene guardar datos simples e indivisibles: separa nombre y apellido en vez de uno solo.", "u": "Decidir qué columnas tendrá cada tabla.\n\nQuieres decidir qué datos guardar de cada alumno: nombre, correo y fecha de nacimiento.", "p": ["Un atributo describe una característica de una entidad.", "Cada atributo se convierte en una columna.", "Es mejor guardar datos simples en columnas separadas."], "c": "CREATE TABLE alumnos (\n  id INT PRIMARY KEY,\n  nombre VARCHAR(40),       -- atributo: nombre\n  apellido VARCHAR(40),     -- atributo: apellido (separado)\n  correo VARCHAR(80),       -- atributo: correo\n  nacimiento DATE           -- atributo: fecha de nacimiento\n);", "h": "Define cinco atributos de un alumno como columnas separadas.", "r": "Reto mental: Cada atributo de una entidad se convierte en una ___. (7 letras)", "e": "Guardar nombre y apellido juntos en una sola columna."},
  {"m": "Modelado de datos", "t": "Relación entre entidades", "x": "Vínculo que une a dos entidades.\n\nUn alumno se matricula en cursos, un cliente hace pedidos, un autor escribe libros. Esas conexiones son relaciones. Las relaciones se representan con verbos y luego se traducen en claves que conectan las tablas.", "u": "Reflejar cómo se conectan los datos en la vida real.\n\nQuieres expresar que un cliente «realiza» pedidos, conectando dos entidades.", "p": ["Una relación une dos entidades.", "Las relaciones suelen describirse con verbos.", "Las relaciones se traducen en claves entre tablas."], "c": "-- clientes ---realiza---> pedidos\n-- La relación se guarda con un campo que apunta al cliente\nCREATE TABLE pedidos (\n  id INT PRIMARY KEY,\n  cliente_id INT           -- aquí vive la relación\n);", "h": "Expresa que un pedido pertenece a un cliente con un campo que lo apunta.", "r": "Reto mental: Una conexión entre dos entidades es una ___. (8 letras)", "e": "Olvidar relacionar las tablas y duplicar datos."},
  {"m": "Modelado de datos", "t": "Cardinalidad", "x": "Número de elementos de una entidad que se relacionan con otra.\n\nPregúntate dos veces. ¿Un cliente puede tener varios pedidos? Sí. ¿Un pedido puede tener varios clientes? No. Entonces es una relación de uno a muchos. Esa respuesta decide dónde se coloca la clave que conecta las tablas.", "u": "Saber si una relación es de uno a uno, uno a muchos o muchos a muchos.\n\nTe preguntas cuántos pedidos puede tener un cliente y cuántos clientes un pedido.", "p": ["La cardinalidad indica cuántos elementos se relacionan.", "Las tres cardinalidades son 1:1, 1:N y N:M.", "La cardinalidad decide dónde va la clave de conexión."], "c": "-- Pregunta 1: ¿un cliente tiene varios pedidos?  SÍ  (muchos)\n-- Pregunta 2: ¿un pedido tiene varios clientes?  NO  (uno)\n-- Resultado: relación UNO a MUCHOS (1:N)\nSELECT 'cliente 1 --- N pedidos' AS cardinalidad;", "h": "Razona la cardinalidad entre clientes y pedidos con dos preguntas.", "r": "Reto mental: Las tres cardinalidades son 1:1, 1:N y ___. (3 caracteres)", "e": "Decidir la cardinalidad sin hacerse las dos preguntas."},
  {"m": "Modelado de datos", "t": "Relación uno a muchos", "x": "Relación donde un elemento se conecta con varios de otra tabla.\n\nEs la relación más común. La clave foránea se coloca en el lado «muchos»: cada pedido guarda el id de su cliente. Así un cliente tiene muchos pedidos y cada pedido pertenece a un solo cliente.", "u": "Modelar casos como cliente y pedidos.\n\nQuieres modelar que un autor escribe muchos libros, pero cada libro tiene un único autor.", "p": ["En 1:N, la clave foránea va en la tabla del lado «muchos».", "Un cliente puede tener muchos pedidos.", "Cada pedido pertenece a un solo cliente."], "c": "CREATE TABLE autores (id INT PRIMARY KEY, nombre VARCHAR(40));\nCREATE TABLE libros (\n  id INT PRIMARY KEY,\n  titulo VARCHAR(60),\n  autor_id INT,                          -- la clave va en el lado «muchos»\n  FOREIGN KEY (autor_id) REFERENCES autores(id)\n);", "h": "Conecta muchos libros con un único autor mediante clave foránea.", "r": "Reto mental: En una relación 1:N, la clave foránea va en la tabla del lado ___. (6 letras)", "e": "Colocar la clave foránea en el lado «uno»."},
  {"m": "Modelado de datos", "t": "Relación muchos a muchos", "x": "Relación donde ambos lados pueden tener varios elementos.\n\nUn alumno se apunta a varios cursos y un curso tiene varios alumnos. Esta relación no se puede resolver con una sola clave: se necesita una tercera tabla intermedia que guarde las parejas alumno-curso.", "u": "Modelar casos como alumnos y cursos.\n\nUn alumno puede matricularse en varios cursos y un curso tiene varios alumnos.", "p": ["En N:M ambos lados pueden tener varios elementos.", "Una relación N:M necesita una tabla intermedia.", "Alumnos y cursos suelen formar una relación N:M."], "c": "-- alumnos N --- M cursos  se resuelve con una tabla intermedia\nCREATE TABLE matriculas (\n  alumno_id INT,\n  curso_id  INT,\n  PRIMARY KEY (alumno_id, curso_id)   -- cada pareja solo una vez\n);", "h": "Resuelve una relación de muchos a muchos con una tabla de parejas.", "r": "Reto mental: Una relación N:M necesita una tabla ___. (11 letras)", "e": "Intentar resolver N:M con una sola clave foránea."},
  {"m": "Modelado de datos", "t": "Tabla intermedia", "x": "Tabla que une otras dos con una clave de cada una.\n\nLa tabla intermedia (también llamada de unión o asociativa) tiene dos claves foráneas, una por cada tabla. Puede añadir datos propios de la relación, como la nota del alumno en ese curso o la fecha de matrícula.", "u": "Guardar las parejas de una relación muchos a muchos.\n\nQuieres guardar la nota que cada alumno obtuvo en cada curso.", "p": ["La tabla intermedia tiene una clave foránea por cada tabla unida.", "Puede guardar datos propios de la relación.", "Se usa para relaciones muchos a muchos."], "c": "CREATE TABLE notas (\n  alumno_id INT,\n  curso_id  INT,\n  nota DECIMAL(4,2),                  -- dato propio de la relación\n  PRIMARY KEY (alumno_id, curso_id),\n  FOREIGN KEY (alumno_id) REFERENCES alumnos(id),\n  FOREIGN KEY (curso_id)  REFERENCES cursos(id)\n);", "h": "Guarda la nota de cada alumno en cada curso en una tabla de unión.", "r": "Reto mental: La tabla intermedia tiene una clave ___ por cada tabla que une. (8 letras)", "e": "Guardar la nota en la tabla de alumnos."},
  {"m": "Modelado de datos", "t": "Relación uno a uno", "x": "Relación donde cada elemento se conecta con uno solo del otro lado.\n\nUn usuario tiene un solo perfil y un perfil pertenece a un solo usuario. A menudo se unen en una sola tabla, pero se separan cuando los datos son opcionales, sensibles (como credenciales) o muy extensos. La clave foránea lleva UNIQUE para asegurar el uno a uno.", "u": "Separar datos opcionales o delicados en otra tabla.\n\nCada usuario tiene exactamente un perfil con datos opcionales y cada perfil es de un único usuario.", "p": ["En 1:1 cada elemento se conecta con uno solo del otro lado.", "Se separa en otra tabla cuando los datos son opcionales o sensibles.", "Una clave foránea UNIQUE garantiza el uno a uno."], "c": "CREATE TABLE perfiles (\n  id INT PRIMARY KEY,\n  usuario_id INT UNIQUE,            -- UNIQUE asegura el uno a uno\n  biografia TEXT,\n  FOREIGN KEY (usuario_id) REFERENCES usuarios(id)\n);", "h": "Vincula cada perfil con un único usuario.", "r": "Reto mental: Para garantizar una relación 1:1, la clave foránea debe ser ___. (6 letras)", "e": "Olvidar UNIQUE y permitir varios perfiles por usuario."},
  {"m": "Modelado de datos", "t": "Diagrama entidad-relación", "x": "Dibujo que muestra entidades, atributos y relaciones.\n\nSe dibuja con rectángulos para las entidades, óvalos para los atributos y rombos o líneas para las relaciones. Un buen diagrama se hace en papel o con herramientas como Workbench o dbdiagram.io antes de escribir una sola línea de SQL.", "u": "Planificar la base de datos antes de crearla.\n\nQuieres dibujar las entidades y sus relaciones antes de crear ninguna tabla.", "p": ["Un diagrama ER dibuja entidades y relaciones.", "Se hace antes de crear las tablas.", "Workbench puede generar diagramas ER."], "c": "-- Diagrama en texto:\n-- [clientes] 1 ----- N [pedidos] N ----- M [productos]\n-- Cada [caja] sería una tabla; las líneas, claves foráneas.\nSELECT 'primero se dibuja, luego se crea' AS consejo;", "h": "Describe en texto un diagrama con tres entidades y sus relaciones.", "r": "Reto mental: Las siglas del diagrama que muestra entidades y relaciones son ___. (2 letras)", "e": "Empezar a crear tablas sin planificar el modelo."},
  {"m": "Modelado de datos", "t": "Clave foránea", "x": "Columna que apunta a la clave primaria de otra tabla.\n\nLa clave foránea (FOREIGN KEY) guarda el id de otra tabla: pedidos.cliente_id apunta a clientes.id. El gestor impide guardar un pedido de un cliente que no existe y también impide borrar un cliente que tiene pedidos.", "u": "Conectar tablas y mantener los datos coherentes.\n\nQuieres impedir que se guarde un pedido de un cliente que no existe.", "p": ["Una clave foránea apunta a la clave primaria de otra tabla.", "Impide guardar valores que no existen en la tabla referenciada.", "Mantiene la integridad entre tablas."], "c": "CREATE TABLE pedidos (\n  id INT PRIMARY KEY,\n  cliente_id INT,\n  total DECIMAL(8,2),\n  FOREIGN KEY (cliente_id) REFERENCES clientes(id)   -- apunta a clientes\n);\nINSERT INTO pedidos VALUES (1, 9999, 50);   -- falla si el cliente 9999 no existe", "h": "Impide guardar un pedido que apunta a un cliente inexistente.", "r": "Reto mental: La clave que apunta a la clave primaria de otra tabla es la clave ___. (7 letras)", "e": "Guardar ids de clientes que no existen. Faltan los paréntesis: FOREIGN KEY (cliente_id) REFERENCES clientes(id)."},
  {"m": "Modelado de datos", "t": "Tipos numéricos", "x": "Tipos de dato para guardar números enteros y decimales.\n\nINT guarda enteros (edades, cantidades). DECIMAL(8,2) guarda números con decimales exactos, ideal para dinero: 8 dígitos en total, 2 de ellos decimales. FLOAT y DOUBLE son aproximados y no se recomiendan para dinero.", "u": "Elegir cómo guardar cantidades, edades y precios.\n\nQuieres guardar precios con céntimos sin errores de redondeo.", "p": ["INT guarda números enteros.", "DECIMAL guarda decimales exactos y es adecuado para dinero.", "FLOAT guarda decimales aproximados."], "c": "CREATE TABLE productos (\n  id INT PRIMARY KEY,\n  stock INT,                -- entero: 25\n  precio DECIMAL(8,2),      -- exacto: 1234.56\n  peso FLOAT                -- aproximado: 0.350\n);", "h": "Guarda enteros, precios exactos y pesos aproximados.", "r": "Reto mental: El tipo para números enteros es ___. (3 letras)", "e": "Usar FLOAT para guardar dinero."},
  {"m": "Modelado de datos", "t": "Tipos de texto", "x": "Tipos de dato para guardar cadenas de caracteres.\n\nCHAR(n) reserva siempre n caracteres (útil para códigos fijos). VARCHAR(n) guarda hasta n caracteres y ocupa solo lo necesario: es el más común. TEXT sirve para textos largos como biografías o comentarios.", "u": "Guardar nombres, direcciones y descripciones.\n\nQuieres guardar nombres de hasta 50 caracteres ocupando solo el espacio necesario.", "p": ["VARCHAR guarda texto de longitud variable hasta un máximo.", "CHAR reserva una longitud fija.", "TEXT sirve para textos largos."], "c": "CREATE TABLE usuarios (\n  id INT PRIMARY KEY,\n  pais CHAR(2),             -- siempre 2 letras: PE, MX\n  nombre VARCHAR(50),       -- hasta 50 caracteres\n  biografia TEXT            -- texto largo\n);", "h": "Elige el tipo de texto adecuado para código, nombre y biografía.", "r": "Reto mental: El tipo de texto de longitud variable más común es ___. (7 letras)", "e": "Usar VARCHAR(5) para un campo que necesita más caracteres."},
  {"m": "Modelado de datos", "t": "Fechas y horas", "x": "Tipos de dato para guardar fechas y momentos exactos.\n\nDATE guarda solo la fecha (2026-03-15). TIME guarda una hora y DATETIME o TIMESTAMP guardan fecha y hora juntas. Nunca guardes fechas como texto: con el tipo correcto puedes ordenar, restar y filtrar fechas.", "u": "Registrar cuándo ocurre algo.\n\nQuieres registrar el momento exacto, con fecha y hora, en que se hizo un pedido.", "p": ["DATE guarda solo la fecha.", "DATETIME guarda fecha y hora.", "No conviene guardar fechas como texto."], "c": "CREATE TABLE pedidos (\n  id INT PRIMARY KEY,\n  fecha_entrega DATE,                          -- solo día: 2026-03-15\n  creado DATETIME DEFAULT CURRENT_TIMESTAMP    -- día y hora automáticos\n);", "h": "Guarda la fecha de entrega y el momento exacto de creación del pedido.", "r": "Reto mental: El tipo que guarda solo la fecha es ___. (4 letras)", "e": "Guardar fechas como texto."},
  {"m": "Modelado de datos", "t": "Valores booleanos", "x": "Tipo de dato que guarda verdadero o falso.\n\nMySQL no tiene un tipo booleano propio: BOOLEAN es un alias de TINYINT(1), donde 0 es falso y 1 es verdadero. Otras bases como PostgreSQL sí tienen BOOLEAN. Se usa para banderas como activo, verificado o eliminado.", "u": "Guardar estados como activo, pagado o leído.\n\nQuieres guardar si un usuario está activo o no.", "p": ["En MySQL, BOOLEAN equivale a TINYINT(1).", "El valor 0 significa falso y el 1 verdadero.", "Los booleanos guardan estados como activo o pagado."], "c": "CREATE TABLE usuarios (\n  id INT PRIMARY KEY,\n  activo BOOLEAN DEFAULT TRUE       -- 1 = activo, 0 = inactivo\n);\nINSERT INTO usuarios (id, activo) VALUES (1, FALSE);", "h": "Guarda con un booleano si un usuario está activo o no.", "r": "Reto mental: En MySQL, el valor 0 de un booleano significa ___. (5 letras)", "e": "Guardar «sí» y «no» como texto."},
  {"m": "Modelado de datos", "t": "NOT NULL", "x": "Restricción que obliga a que la columna tenga un valor.\n\nNULL significa «sin valor» y no es lo mismo que cero o texto vacío. Si una columna es NOT NULL, intentar insertar una fila sin ese dato produce un error. Úsalo en datos imprescindibles como el nombre o el correo.", "u": "Evitar campos importantes vacíos.\n\nQuieres que sea obligatorio escribir el nombre al insertar una fila.", "p": ["NOT NULL impide dejar la columna sin valor.", "NULL significa ausencia de valor.", "NULL no es lo mismo que cero ni que texto vacío."], "c": "CREATE TABLE clientes (\n  id INT PRIMARY KEY,\n  nombre VARCHAR(40) NOT NULL,     -- obligatorio\n  telefono VARCHAR(15)             -- opcional: puede ser NULL\n);\nINSERT INTO clientes (id) VALUES (1);   -- falla: falta el nombre", "h": "Exige nombre obligatorio y deja el teléfono como opcional.", "r": "Reto mental: La restricción que obliga a tener valor es NOT ___. (4 letras)", "e": "Confundir NULL con cero o con texto vacío."},
  {"m": "Modelado de datos", "t": "DEFAULT", "x": "Valor automático que se usa cuando no se indica otro.\n\nSi no indicas un valor al insertar, la columna toma el DEFAULT: un estado «pendiente», un contador en 0 o la fecha actual. Reduce errores y simplifica las inserciones.", "u": "Evitar escribir siempre los mismos datos.\n\nQuieres que todo pedido nuevo tenga el estado «pendiente» si no se indica otro.", "p": ["DEFAULT define el valor por omisión de una columna.", "Se usa si al insertar no se indica un valor.", "Puede ser un texto, un número o la fecha actual."], "c": "CREATE TABLE pedidos (\n  id INT PRIMARY KEY,\n  estado VARCHAR(15) DEFAULT 'pendiente',   -- valor por defecto\n  creado DATETIME DEFAULT CURRENT_TIMESTAMP\n);\nINSERT INTO pedidos (id) VALUES (1);        -- estado = 'pendiente'", "h": "Asigna automáticamente un estado y una fecha a cada pedido nuevo.", "r": "Reto mental: El valor que se usa si no se indica otro se define con ___. (7 letras)", "e": "Olvidar el DEFAULT y obligar a escribir siempre el mismo valor."},
  {"m": "Modelado de datos", "t": "AUTO_INCREMENT", "x": "Opción que numera automáticamente cada nueva fila.\n\nCon AUTO_INCREMENT en la clave primaria, MySQL asigna 1, 2, 3… a cada fila nueva. Nunca reutiliza un número ya usado aunque borres filas. Al insertar, simplemente no indicas el id.", "u": "Generar ids únicos sin escribirlos a mano.\n\nQuieres que cada usuario nuevo reciba su id solo, sin escribirlo.", "p": ["AUTO_INCREMENT numera las filas automáticamente.", "Se suele usar en la clave primaria.", "Al insertar no hace falta indicar el id."], "c": "CREATE TABLE usuarios (\n  id INT PRIMARY KEY AUTO_INCREMENT,   -- 1, 2, 3...\n  nombre VARCHAR(40)\n);\nINSERT INTO usuarios (nombre) VALUES ('Ana');    -- id = 1\nINSERT INTO usuarios (nombre) VALUES ('Luis');   -- id = 2", "h": "Deja que MySQL asigne el id de cada usuario nuevo.", "r": "Reto mental: La opción que numera filas automáticamente es ____INCREMENT. (4 letras)", "e": "Escribir ids a mano y provocar repetidos. Una columna AUTO_INCREMENT debe ser clave primaria: id INT PRIMARY KEY AUTO_INCREMENT."},
  {"m": "Modelado de datos", "t": "Redundancia de datos", "x": "Repetición innecesaria de la misma información.\n\nSi en la tabla pedidos escribes el nombre y la dirección del cliente en cada pedido, repites datos. Si el cliente cambia de dirección tendrías que corregir muchas filas y podrían quedar valores distintos. La solución es guardar al cliente una sola vez y referenciarlo.", "u": "Detectar tablas mal diseñadas.\n\nEl nombre y la dirección de un cliente están repetidos en cada uno de sus pedidos.", "p": ["La redundancia es repetir los mismos datos sin necesidad.", "La redundancia dificulta las actualizaciones y crea inconsistencias.", "Se evita guardando cada dato una sola vez y referenciándolo."], "c": "-- MAL: se repite el cliente en cada pedido\n-- pedidos(id, cliente_nombre, cliente_direccion, total)\n-- BIEN: el cliente se guarda una sola vez\n-- clientes(id, nombre, direccion)\n-- pedidos(id, cliente_id, total)\nSELECT 'guarda cada dato una sola vez' AS regla;", "h": "Contrasta una tabla con datos repetidos y otra con datos guardados una sola vez.", "r": "Reto mental: Repetir innecesariamente la misma información es ___. (11 letras: redundancia)", "e": "Copiar los datos del cliente en cada pedido."},
  {"m": "Modelado de datos", "t": "Normalización", "x": "Proceso de organizar las tablas para evitar repeticiones y errores.\n\nLa primera forma normal pide valores simples en cada celda (nada de listas). La segunda, que todo dependa de la clave completa. La tercera, que las columnas no dependan de otras columnas no clave. Con tres formas normales la mayoría de los diseños quedan sólidos.", "u": "Obtener un diseño limpio y fácil de mantener.\n\nQuieres reorganizar tus tablas siguiendo reglas para eliminar repeticiones.", "p": ["La normalización organiza las tablas para evitar redundancia.", "La primera forma normal exige un valor simple por celda.", "Las tres primeras formas normales bastan en la mayoría de casos."], "c": "-- Primera forma normal: nada de listas en una celda\n-- MAL:  alumnos(id, nombre, cursos = 'HTML, CSS, SQL')\n-- BIEN: una fila por cada pareja alumno-curso\n-- matriculas(alumno_id, curso_id)\nSELECT '1FN: un valor simple por celda' AS regla;", "h": "Separa una lista guardada en una celda en filas independientes.", "r": "Reto mental: El proceso de organizar tablas para evitar repeticiones es la ___. (13 letras)", "e": "Guardar listas separadas por comas en una sola celda."},
  {"m": "Modelado de datos", "t": "Convenciones de nombres", "x": "Reglas para nombrar tablas y columnas de forma coherente.\n\nElige un estilo y úsalo siempre: minúsculas con guion bajo (fecha_pedido), tablas en plural (clientes) o singular, pero sin mezclar. Evita espacios, tildes y palabras reservadas como order o group. La clave foránea suele llamarse tabla_id.", "u": "Mantener la base ordenada y fácil de entender.\n\nQuieres que todos los nombres de tablas y columnas sigan el mismo estilo claro.", "p": ["Los nombres deben seguir un estilo coherente.", "Evita espacios, tildes y palabras reservadas.", "La clave foránea suele llamarse tabla_id."], "c": "-- Buen estilo: minúsculas, guion bajo y sin tildes\nCREATE TABLE clientes (id INT PRIMARY KEY, nombre_completo VARCHAR(80));\nCREATE TABLE pedidos  (id INT PRIMARY KEY, cliente_id INT, fecha_pedido DATE);\n-- Mal estilo: 'Nombre Completo', ÓrdenDelCliente, order", "h": "Usa nombres en minúsculas con guion bajo y claves tabla_id.", "r": "Reto mental: Los nombres de columnas suelen escribirse en minúsculas con guion ___. (4 letras)", "e": "Usar espacios, tildes o palabras reservadas en los nombres."},
  {"m": "SQL esencial", "t": "CREATE DATABASE y USE", "x": "Comandos para crear una base de datos y empezar a usarla.\n\nCREATE DATABASE crea una base vacía. USE la selecciona: a partir de ahí los comandos afectan a esa base. CREATE DATABASE IF NOT EXISTS evita un error si ya existía. Los comandos SQL terminan en punto y coma.", "u": "Preparar el espacio donde irán las tablas.\n\nQuieres crear la base «escuela» y empezar a trabajar dentro de ella.", "p": ["CREATE DATABASE crea una base de datos nueva.", "USE selecciona la base con la que se trabaja.", "Cada instrucción SQL termina con punto y coma."], "c": "CREATE DATABASE IF NOT EXISTS escuela;   -- crea la base si no existe\nUSE escuela;                              -- a partir de aquí trabajamos en ella\nSHOW TABLES;                              -- todavía no hay tablas", "h": "Crea la base escuela, la selecciona y lista sus tablas.", "r": "Reto mental: El comando que selecciona la base de datos de trabajo es ___. (3 letras)", "e": "Olvidar USE y crear tablas en otra base."},
  {"m": "SQL esencial", "t": "CREATE TABLE", "x": "Comando que crea una tabla con sus columnas.\n\nDespués del nombre de la tabla, entre paréntesis, se escribe cada columna con su tipo y restricciones, separadas por comas. La última columna no lleva coma. Si repites el nombre de una tabla existente, MySQL da error.", "u": "Definir la estructura donde se guardarán los datos.\n\nQuieres crear una tabla de alumnos con id, nombre, curso y nota.", "p": ["CREATE TABLE define las columnas y sus tipos.", "Las columnas se separan con comas, salvo la última.", "No se puede crear una tabla con un nombre ya usado."], "c": "CREATE TABLE alumnos (\n  id INT PRIMARY KEY AUTO_INCREMENT,\n  nombre VARCHAR(40) NOT NULL,\n  curso VARCHAR(20),\n  nota DECIMAL(4,2)\n);", "h": "Crea la tabla alumnos con cuatro columnas y sus restricciones.", "r": "Reto mental: Escribe el comando para crear una tabla (dos palabras): CREATE ___.", "e": "Dejar una coma después de la última columna. Sobra la coma al final de la última columna."},
  {"m": "SQL esencial", "t": "INSERT INTO", "x": "Comando que añade filas nuevas a una tabla.\n\nSe escribe INSERT INTO tabla (columnas) VALUES (valores). Los textos y fechas van entre comillas simples y los números sin comillas. Puedes insertar varias filas a la vez separándolas con comas. Indicar las columnas hace el comando más seguro.", "u": "Guardar datos nuevos.\n\nQuieres añadir tres alumnos nuevos a la tabla con un solo comando.", "p": ["INSERT INTO añade filas a una tabla.", "Los textos y fechas van entre comillas simples.", "Se pueden insertar varias filas en un solo comando."], "c": "INSERT INTO alumnos (nombre, curso, nota) VALUES\n  ('Ana',   'HTML',   9.1),     -- texto entre comillas, número sin ellas\n  ('Luis',  'Python', 6.4),\n  ('Marta', 'SQL',    8.2);", "h": "Inserta tres alumnos de una sola vez.", "r": "Reto mental: Escribe el comando para añadir filas (dos palabras): INSERT ___.", "e": "Olvidar las comillas en un texto. El texto Ana debe ir entre comillas simples: 'Ana'."},
  {"m": "SQL esencial", "t": "SELECT", "x": "Comando que consulta y devuelve datos de una tabla.\n\nSELECT columnas FROM tabla; es la consulta más sencilla. Devuelve un resultado con filas y columnas, pero no cambia nada en la tabla. SELECT * FROM tabla devuelve todas las columnas, útil para explorar pero poco recomendable en aplicaciones.", "u": "Leer información guardada.\n\nQuieres ver todos los datos guardados en la tabla alumnos.", "p": ["SELECT lee datos sin modificarlos.", "SELECT * devuelve todas las columnas.", "El resultado de un SELECT tiene filas y columnas."], "c": "SELECT * FROM alumnos;                 -- todas las columnas\nSELECT nombre, nota FROM alumnos;      -- solo esas dos\n-- Ninguna de las dos consultas cambia los datos", "h": "Consulta todas las columnas y luego solo nombre y nota.", "r": "Reto mental: Escribe el comando para consultar datos: ___.", "e": "Usar SELECT * en aplicaciones reales sin necesitarlo."},
  {"m": "SQL esencial", "t": "Elegir columnas", "x": "Forma de pedir solo las columnas que se necesitan.\n\nEn vez de *, escribe los nombres de las columnas separados por comas. Obtienes un resultado más claro y la base de datos trabaja menos. Además, tu código no se rompe si alguien añade columnas nuevas a la tabla.", "u": "Traer menos datos y hacer consultas más rápidas.\n\nSolo necesitas el nombre y la nota de cada alumno, no el resto de columnas.", "p": ["Elegir columnas reduce los datos que se transfieren.", "Las columnas se separan con comas.", "Nombrar las columnas hace el código más estable."], "c": "-- Mejor: pedir solo lo necesario\nSELECT nombre, nota\nFROM alumnos;\n-- El orden de las columnas en el resultado es el que escribes\nSELECT nota, nombre FROM alumnos;", "h": "Pide solo dos columnas y las muestra en el orden escrito.", "r": "Reto mental: Al elegir varias columnas, se separan con ___. (una coma)", "e": "Pedir todas las columnas cuando solo se usan dos."},
  {"m": "SQL esencial", "t": "WHERE", "x": "Cláusula que filtra las filas que cumplen una condición.\n\nWHERE va después de FROM y deja pasar solo las filas donde la condición es verdadera. Se usa también con UPDATE y DELETE. Olvidarlo en un UPDATE o DELETE afecta a todas las filas, así que revisa siempre su presencia.", "u": "Obtener solo los datos que interesan.\n\nQuieres ver solo los alumnos del curso Python.", "p": ["WHERE filtra las filas según una condición.", "WHERE va después de FROM.", "En UPDATE y DELETE, olvidar WHERE afecta a toda la tabla."], "c": "SELECT nombre, curso\nFROM alumnos\nWHERE curso = 'Python';       -- solo las filas con curso Python", "h": "Filtra los alumnos que cursan Python.", "r": "Reto mental: La cláusula que filtra filas por una condición es ___. (5 letras)", "e": "Olvidar WHERE en un UPDATE o un DELETE. WHERE debe ir después de FROM, no antes."},
  {"m": "SQL esencial", "t": "Operadores de comparación", "x": "Símbolos que comparan valores en una condición.\n\nLos operadores son = (igual), <> o != (distinto), > (mayor), < (menor), >= y <=. Para comparar igualdad se usa un solo signo =, no dos como en otros lenguajes. Los textos se comparan con comillas.", "u": "Decidir qué filas cumplen un criterio numérico o de texto.\n\nQuieres ver los alumnos con nota mayor o igual que 7.", "p": ["En SQL, la igualdad se escribe con un solo signo =.", "<> significa distinto de.", ">= significa mayor o igual."], "c": "SELECT nombre, nota FROM alumnos WHERE nota >= 7;      -- mayor o igual\nSELECT nombre FROM alumnos WHERE curso <> 'HTML';      -- distinto de HTML\nSELECT nombre FROM alumnos WHERE nota = 10;            -- igual (un solo =)", "h": "Compara notas con mayor o igual, distinto e igual.", "r": "Reto mental: El operador SQL que significa «distinto de» es ___. (2 caracteres)", "e": "Usar == en lugar de = para comparar."},
  {"m": "SQL esencial", "t": "AND y OR", "x": "Operadores que combinan varias condiciones.\n\nAND exige que se cumplan todas las condiciones. OR exige que se cumpla al menos una. AND se evalúa antes que OR, así que usa paréntesis para dejar clara tu intención y evitar resultados inesperados.", "u": "Filtrar con más de un criterio a la vez.\n\nQuieres alumnos del curso SQL con nota mayor que 8 a la vez.", "p": ["AND exige que se cumplan todas las condiciones.", "OR exige que se cumpla al menos una.", "Los paréntesis aclaran el orden de evaluación."], "c": "SELECT nombre FROM alumnos\nWHERE curso = 'SQL' AND nota > 8;          -- ambas condiciones\nSELECT nombre FROM alumnos\nWHERE curso = 'SQL' OR curso = 'Python';   -- al menos una", "h": "Combina condiciones que deben cumplirse todas y otras en que basta una.", "r": "Reto mental: El operador que exige que se cumplan todas las condiciones es ___. (3 letras)", "e": "Mezclar AND y OR sin paréntesis."},
  {"m": "SQL esencial", "t": "NOT", "x": "Operador que invierte el resultado de una condición.\n\nNOT delante de una condición la invierte: NOT curso = 'HTML' elige todos menos HTML. Se usa también con otras palabras: NOT IN, NOT LIKE, NOT BETWEEN, IS NOT NULL. Para comparaciones simples, <> suele ser más directo.", "u": "Excluir filas que cumplen un criterio.\n\nQuieres ver todos los alumnos excepto los del curso HTML.", "p": ["NOT invierte una condición.", "Se combina con IN, LIKE, BETWEEN e IS NULL.", "Para comparaciones sencillas se puede usar <>."], "c": "SELECT nombre FROM alumnos WHERE NOT curso = 'HTML';       -- todos menos HTML\nSELECT nombre FROM alumnos WHERE curso NOT IN ('HTML', 'CSS');\nSELECT nombre FROM alumnos WHERE nombre NOT LIKE 'A%';", "h": "Excluye alumnos usando NOT en tres formas distintas.", "r": "Reto mental: El operador que invierte una condición es ___. (3 letras)", "e": "Olvidar que NOT cambia el significado de toda la condición."},
  {"m": "SQL esencial", "t": "LIKE", "x": "Operador que busca texto con patrones.\n\nCon LIKE el símbolo % significa «cualquier cantidad de caracteres» y _ significa «exactamente un carácter». 'A%' son los que empiezan por A, '%a' los que terminan en a y '%an%' los que contienen «an».", "u": "Encontrar nombres que empiezan, terminan o contienen algo.\n\nQuieres encontrar todos los nombres que empiezan por la letra A.", "p": ["El símbolo % representa cualquier cantidad de caracteres.", "El símbolo _ representa exactamente un carácter.", "LIKE 'A%' busca textos que empiezan por A."], "c": "SELECT nombre FROM alumnos WHERE nombre LIKE 'A%';    -- empieza por A\nSELECT nombre FROM alumnos WHERE nombre LIKE '%a';    -- termina en a\nSELECT nombre FROM alumnos WHERE nombre LIKE '%ar%';  -- contiene «ar»\nSELECT nombre FROM alumnos WHERE nombre LIKE '_na';   -- 3 letras que acaban en na", "h": "Busca nombres que empiezan, terminan o contienen ciertas letras.", "r": "Reto mental: El comodín de LIKE que significa «cualquier cantidad de caracteres» es ___. (un carácter)", "e": "Usar = en lugar de LIKE cuando se busca con comodines."},
  {"m": "SQL esencial", "t": "IN", "x": "Operador que comprueba si un valor está en una lista.\n\ncurso IN ('HTML', 'CSS', 'SQL') equivale a tres condiciones unidas con OR, pero se lee mejor. También acepta el resultado de una subconsulta. Con NOT IN se excluyen los valores de la lista.", "u": "Escribir muchas condiciones OR de forma corta.\n\nQuieres ver alumnos de tres cursos concretos sin escribir tres condiciones con OR.", "p": ["IN comprueba si un valor está dentro de una lista.", "IN equivale a varias condiciones OR.", "NOT IN excluye los valores de la lista."], "c": "SELECT nombre, curso FROM alumnos\nWHERE curso IN ('HTML', 'CSS', 'SQL');\n-- equivale a: curso = 'HTML' OR curso = 'CSS' OR curso = 'SQL'", "h": "Filtra alumnos que están en cualquiera de tres cursos.", "r": "Reto mental: El operador que comprueba si un valor está en una lista es ___. (2 letras)", "e": "Olvidar los paréntesis en la lista de IN."},
  {"m": "SQL esencial", "t": "BETWEEN", "x": "Operador que comprueba si un valor está en un rango.\n\nnota BETWEEN 6 AND 8 incluye los dos extremos (6 y 8). Sirve con números, fechas y textos. Es equivalente a nota >= 6 AND nota <= 8. Escribe siempre primero el valor menor.", "u": "Filtrar números o fechas entre dos límites.\n\nQuieres alumnos con nota entre 6 y 8, ambos incluidos.", "p": ["BETWEEN incluye los dos extremos del rango.", "Funciona con números y fechas.", "El primer valor debe ser el menor."], "c": "SELECT nombre, nota FROM alumnos\nWHERE nota BETWEEN 6 AND 8;         -- 6 y 8 también entran\nSELECT * FROM pedidos\nWHERE fecha BETWEEN '2026-01-01' AND '2026-03-31';", "h": "Filtra notas y fechas dentro de un rango con límites incluidos.", "r": "Reto mental: El operador que comprueba un rango se escribe ___. (7 letras)", "e": "Escribir el valor mayor antes que el menor."},
  {"m": "SQL esencial", "t": "IS NULL", "x": "Comprobación de si un valor está ausente.\n\nNULL no es un valor, así que no se compara con =. Hay que escribir IS NULL o IS NOT NULL. Escribir WHERE telefono = NULL nunca devuelve filas, porque cualquier comparación con NULL no es verdadera.", "u": "Encontrar o excluir datos que faltan.\n\nQuieres encontrar los clientes que no tienen teléfono registrado.", "p": ["NULL se comprueba con IS NULL, no con =.", "IS NOT NULL elige las filas que sí tienen valor.", "Comparar con = NULL nunca devuelve resultados."], "c": "SELECT nombre FROM clientes WHERE telefono IS NULL;        -- sin teléfono\nSELECT nombre FROM clientes WHERE telefono IS NOT NULL;    -- con teléfono\n-- MAL: WHERE telefono = NULL   (no devuelve nada)", "h": "Separa clientes con teléfono de los que no lo tienen.", "r": "Reto mental: Para buscar valores ausentes se escribe IS ___. (4 letras)", "e": "Comparar con = NULL en lugar de IS NULL. Con NULL se usa IS NULL, no =."},
  {"m": "SQL esencial", "t": "ORDER BY", "x": "Cláusula que ordena los resultados.\n\nORDER BY nota ordena de menor a mayor (ASC, por defecto) y ORDER BY nota DESC de mayor a menor. Puedes ordenar por varias columnas separadas por comas. Se escribe después de WHERE.", "u": "Mostrar los datos de menor a mayor o al revés.\n\nQuieres ver a los alumnos de la nota más alta a la más baja.", "p": ["ORDER BY ordena el resultado de la consulta.", "ASC ordena de menor a mayor y DESC de mayor a menor.", "ORDER BY va después de WHERE."], "c": "SELECT nombre, nota FROM alumnos\nORDER BY nota DESC;                       -- de mayor a menor\nSELECT nombre, curso, nota FROM alumnos\nORDER BY curso ASC, nota DESC;            -- por curso y, dentro, por nota", "h": "Ordena por nota descendente y luego por curso y nota.", "r": "Reto mental: La cláusula que ordena resultados es ORDER ___. (2 letras)", "e": "Olvidar DESC y obtener el orden contrario."},
  {"m": "SQL esencial", "t": "LIMIT", "x": "Cláusula que limita cuántas filas devuelve la consulta.\n\nLIMIT 3 devuelve como máximo tres filas. Combinado con ORDER BY, obtienes «los 3 mejores». LIMIT 10 OFFSET 20 salta 20 filas y devuelve las 10 siguientes, que es la base de la paginación.", "u": "Mostrar solo las primeras filas o paginar resultados.\n\nQuieres ver solo los tres alumnos con mejor nota.", "p": ["LIMIT restringe el número de filas devueltas.", "LIMIT con ORDER BY permite obtener los primeros o los mejores.", "OFFSET salta un número de filas."], "c": "SELECT nombre, nota FROM alumnos\nORDER BY nota DESC\nLIMIT 3;                                  -- los 3 mejores\nSELECT nombre FROM alumnos\nORDER BY id LIMIT 10 OFFSET 20;           -- página 3 de 10 en 10", "h": "Obtiene los tres mejores alumnos y una página de resultados.", "r": "Reto mental: La cláusula que limita el número de filas es ___. (5 letras)", "e": "Usar LIMIT sin ORDER BY y obtener filas sin criterio."},
  {"m": "SQL esencial", "t": "DISTINCT", "x": "Palabra que elimina los valores repetidos del resultado.\n\nSELECT DISTINCT curso FROM alumnos devuelve cada curso una sola vez aunque tenga muchos alumnos. Con varias columnas, elimina las combinaciones repetidas. Va justo después de SELECT.", "u": "Obtener una lista sin duplicados.\n\nQuieres una lista de los cursos que existen, sin que se repitan.", "p": ["DISTINCT elimina filas repetidas del resultado.", "DISTINCT va justo después de SELECT.", "Con varias columnas elimina combinaciones repetidas."], "c": "SELECT curso FROM alumnos;              -- repite HTML, Python, HTML...\nSELECT DISTINCT curso FROM alumnos;     -- cada curso una sola vez", "h": "Compara la lista con repetidos y la lista de cursos únicos.", "r": "Reto mental: La palabra que elimina duplicados es ___. (8 letras)", "e": "Creer que DISTINCT borra los datos de la tabla."},
  {"m": "SQL esencial", "t": "Alias con AS", "x": "Nombre temporal que se da a una columna o tabla en la consulta.\n\nSELECT nota * 10 AS nota_sobre_100 pone un nombre claro a una columna calculada. También se aplica a tablas: FROM alumnos AS a. El alias solo existe durante la consulta, no cambia nada en la base. Los alias con espacios van entre comillas.", "u": "Hacer más legibles los resultados y las consultas.\n\nQuieres que la columna calculada nota * 10 aparezca con un nombre claro.", "p": ["AS da un nombre temporal a una columna o tabla.", "El alias no modifica la base de datos.", "Los alias son muy útiles con columnas calculadas."], "c": "SELECT nombre,\n       nota * 10 AS nota_sobre_100        -- alias de la columna calculada\nFROM alumnos AS a;                        -- alias de la tabla\n-- El alias vive solo durante la consulta", "h": "Da nombre claro a una columna calculada y a la tabla consultada.", "r": "Reto mental: La palabra que da un nombre temporal es ___. (2 letras)", "e": "Creer que el alias cambia el nombre real de la columna."},
  {"m": "SQL esencial", "t": "UPDATE", "x": "Comando que modifica datos de filas existentes.\n\nUPDATE tabla SET columna = valor WHERE condición; cambia los datos de las filas que cumplan la condición. Sin WHERE, cambia todas las filas de la tabla. Antes de ejecutar un UPDATE importante, prueba el mismo WHERE con un SELECT.", "u": "Corregir o actualizar información guardada.\n\nQuieres corregir la nota de Ana, sin tocar a nadie más.", "p": ["UPDATE modifica datos que ya existen.", "Sin WHERE, UPDATE cambia todas las filas.", "Conviene probar el WHERE con un SELECT antes."], "c": "UPDATE alumnos\nSET nota = 9.5                 -- nuevo valor\nWHERE nombre = 'Ana';          -- solo para Ana\n-- Comprueba antes con: SELECT * FROM alumnos WHERE nombre = 'Ana';", "h": "Cambia la nota de un único alumno.", "r": "Reto mental: El comando para modificar datos existentes es ___. (6 letras)", "e": "Olvidar WHERE y cambiar todas las filas. Falta WHERE: así se pondría nota 10 a todos los alumnos."},
  {"m": "SQL esencial", "t": "DELETE", "x": "Comando que borra filas de una tabla.\n\nDELETE FROM tabla WHERE condición; borra las filas indicadas. Sin WHERE, borra todas las filas (pero la tabla sigue existiendo). Borrar es difícil de deshacer, por eso se usa WHERE con cuidado o se marca como «eliminado» en vez de borrar.", "u": "Eliminar datos que ya no se necesitan.\n\nQuieres borrar solo al alumno con id 5.", "p": ["DELETE borra filas de una tabla.", "Sin WHERE, DELETE borra todas las filas.", "La tabla sigue existiendo después de un DELETE."], "c": "DELETE FROM alumnos\nWHERE id = 5;               -- solo esa fila\n-- DELETE FROM alumnos;     -- ¡esto borraría TODAS las filas!", "h": "Borra una única fila indicando su id.", "r": "Reto mental: El comando para borrar filas se escribe DELETE ___ tabla. (4 letras)", "e": "Ejecutar DELETE sin WHERE. Falta la condición después de WHERE (por ejemplo id = 5)."},
  {"m": "SQL esencial", "t": "ALTER TABLE y DROP", "x": "Comandos que cambian o eliminan la estructura de una tabla.\n\nALTER TABLE ... ADD columna añade una columna; DROP COLUMN la quita; MODIFY cambia su tipo. DROP TABLE elimina la tabla entera con todos sus datos y no se puede deshacer. TRUNCATE vacía la tabla manteniendo su estructura.", "u": "Añadir columnas o borrar tablas completas.\n\nQuieres añadir una columna «correo» a una tabla que ya existe.", "p": ["ALTER TABLE modifica la estructura de una tabla.", "DROP TABLE elimina la tabla y todos sus datos.", "TRUNCATE vacía la tabla pero conserva su estructura."], "c": "ALTER TABLE alumnos ADD correo VARCHAR(80);        -- añade una columna\nALTER TABLE alumnos MODIFY nombre VARCHAR(60);      -- cambia el tipo\nALTER TABLE alumnos DROP COLUMN correo;             -- la quita\n-- DROP TABLE alumnos;   -- ¡elimina la tabla entera!", "h": "Añade, modifica y quita una columna con ALTER TABLE.", "r": "Reto mental: El comando que cambia la estructura de una tabla es ___ TABLE. (5 letras)", "e": "Ejecutar DROP TABLE sin copia de seguridad."},
  {"m": "Consultas avanzadas", "t": "COUNT", "x": "Función que cuenta filas o valores.\n\nCOUNT(*) cuenta todas las filas; COUNT(columna) cuenta las filas donde esa columna no es NULL; COUNT(DISTINCT columna) cuenta valores distintos. Es una función de agregación: devuelve un solo valor para todo el conjunto de filas.", "u": "Saber cuántos registros cumplen una condición.\n\nQuieres saber cuántos alumnos hay en la tabla.", "p": ["COUNT(*) cuenta todas las filas.", "COUNT(columna) ignora los valores NULL.", "COUNT(DISTINCT columna) cuenta valores distintos."], "c": "SELECT COUNT(*) AS total_alumnos FROM alumnos;                 -- todas las filas\nSELECT COUNT(telefono) AS con_telefono FROM alumnos;           -- ignora NULL\nSELECT COUNT(DISTINCT curso) AS cursos_distintos FROM alumnos;  -- sin repetir", "h": "Cuenta alumnos, teléfonos registrados y cursos distintos.", "r": "Reto mental: La función que cuenta filas es ___(*). (5 letras)", "e": "Contar con COUNT(columna) esperando incluir los NULL."},
  {"m": "Consultas avanzadas", "t": "SUM y AVG", "x": "Funciones que suman y calculan el promedio.\n\nSUM(columna) suma todos los valores y AVG(columna) calcula la media. Ambas ignoran los NULL. Se pueden filtrar con WHERE antes de calcular. ROUND(AVG(nota), 2) redondea el promedio a dos decimales.", "u": "Obtener totales y medias de datos numéricos.\n\nQuieres saber el total vendido y el precio medio de los pedidos.", "p": ["SUM suma los valores de una columna.", "AVG calcula el promedio de una columna.", "Ambas funciones ignoran los valores NULL."], "c": "SELECT SUM(total) AS vendido,               -- suma de todos los pedidos\n       AVG(total) AS ticket_medio,          -- promedio por pedido\n       ROUND(AVG(total), 2) AS medio_2dec   -- promedio redondeado\nFROM pedidos;", "h": "Calcula el total vendido y el ticket medio redondeado.", "r": "Reto mental: La función que suma valores es ___. (3 letras)", "e": "Calcular promedios con una columna llena de NULL sin darse cuenta."},
  {"m": "Consultas avanzadas", "t": "MIN y MAX", "x": "Funciones que devuelven el valor menor y el mayor.\n\nMIN y MAX funcionan con números, fechas y textos (por orden alfabético). Devuelven solo el valor, no la fila completa. Para obtener la fila del más caro conviene usar ORDER BY precio DESC LIMIT 1.", "u": "Encontrar el más barato, el más caro o la fecha más reciente.\n\nQuieres saber cuál es el precio más bajo y el más alto de los productos.", "p": ["MIN devuelve el valor más pequeño.", "MAX devuelve el valor más grande.", "Funcionan con números, fechas y textos."], "c": "SELECT MIN(precio) AS el_mas_barato,\n       MAX(precio) AS el_mas_caro\nFROM productos;\nSELECT MAX(fecha) AS ultimo_pedido FROM pedidos;   -- con fechas también", "h": "Obtiene el precio mínimo, el máximo y la fecha del último pedido.", "r": "Reto mental: La función que devuelve el valor mayor es ___. (3 letras)", "e": "Esperar que MAX devuelva la fila completa y no solo el valor."},
  {"m": "Consultas avanzadas", "t": "GROUP BY", "x": "Cláusula que agrupa filas para calcular por grupos.\n\nGROUP BY curso crea un grupo por cada curso y las funciones de agregación calculan dentro de cada grupo. Toda columna del SELECT que no sea una función de agregación debe aparecer en el GROUP BY.", "u": "Obtener totales por categoría, cliente o mes.\n\nQuieres saber cuántos alumnos hay en cada curso.", "p": ["GROUP BY crea un grupo por cada valor distinto.", "Las funciones de agregación calculan dentro de cada grupo.", "Las columnas no agregadas del SELECT deben estar en el GROUP BY."], "c": "SELECT curso,\n       COUNT(*)  AS alumnos,\n       AVG(nota) AS media\nFROM alumnos\nGROUP BY curso;               -- una fila por cada curso", "h": "Calcula alumnos y nota media separados por curso.", "r": "Reto mental: La cláusula que agrupa filas es GROUP ___. (2 letras)", "e": "Seleccionar una columna que no está en el GROUP BY. La columna nombre no está en GROUP BY ni dentro de una función de agregación."},
  {"m": "Consultas avanzadas", "t": "HAVING", "x": "Cláusula que filtra los grupos ya calculados.\n\nWHERE filtra filas antes de agrupar y HAVING filtra grupos después de calcular. HAVING es el único sitio donde puedes usar funciones de agregación como condición: HAVING COUNT(*) > 5.", "u": "Quedarse con los grupos que cumplan una condición.\n\nQuieres mostrar solo los cursos que tienen más de 5 alumnos.", "p": ["HAVING filtra grupos después de agrupar.", "WHERE filtra filas antes de agrupar.", "En HAVING sí se pueden usar funciones de agregación."], "c": "SELECT curso, COUNT(*) AS alumnos\nFROM alumnos\nGROUP BY curso\nHAVING COUNT(*) > 5;          -- filtra grupos ya calculados", "h": "Muestra solo los cursos con más de cinco alumnos.", "r": "Reto mental: La cláusula que filtra grupos es ___. (6 letras)", "e": "Usar COUNT(*) dentro de WHERE. No se pueden usar funciones de agregación en WHERE: debe ir en HAVING."},
  {"m": "Consultas avanzadas", "t": "Orden de las cláusulas", "x": "Secuencia fija en la que se escriben las partes de un SELECT.\n\nEl orden de escritura es SELECT, FROM, WHERE, GROUP BY, HAVING, ORDER BY y LIMIT. La base de datos las procesa en otro orden lógico: primero FROM, luego WHERE, GROUP BY, HAVING, SELECT y al final ORDER BY y LIMIT.", "u": "Escribir consultas completas sin errores de sintaxis.\n\nUna consulta con varias cláusulas da error de sintaxis por escribirlas en desorden.", "p": ["El orden de escritura es SELECT, FROM, WHERE, GROUP BY, HAVING, ORDER BY, LIMIT.", "WHERE siempre va antes de GROUP BY.", "LIMIT es la última cláusula."], "c": "SELECT curso, COUNT(*) AS alumnos      -- 1.º qué quiero ver\nFROM alumnos                           -- 2.º de dónde\nWHERE nota >= 5                        -- 3.º filtro de filas\nGROUP BY curso                         -- 4.º agrupar\nHAVING COUNT(*) > 2                    -- 5.º filtro de grupos\nORDER BY alumnos DESC                  -- 6.º ordenar\nLIMIT 3;                               -- 7.º limitar", "h": "Escribe una consulta completa con todas las cláusulas en su orden.", "r": "Reto mental: La cláusula que se escribe justo después de FROM es ___. (5 letras)", "e": "Escribir WHERE después de GROUP BY. WHERE debe ir antes de GROUP BY."},
  {"m": "Consultas avanzadas", "t": "JOIN", "x": "Operación que combina filas de dos tablas relacionadas.\n\nLos datos normalizados están separados: el pedido guarda un cliente_id, no el nombre. Con JOIN unes las tablas usando la condición ON, normalmente la clave foránea igualada a la clave primaria. El resultado parece una sola tabla.", "u": "Mostrar datos que están repartidos en varias tablas.\n\nQuieres mostrar el nombre del cliente junto a cada pedido, aunque estén en tablas distintas.", "p": ["JOIN combina filas de dos tablas.", "ON indica la condición con que se emparejan las filas.", "Se suele unir clave foránea con clave primaria."], "c": "SELECT clientes.nombre, pedidos.total\nFROM pedidos\nJOIN clientes ON pedidos.cliente_id = clientes.id;   -- empareja por la clave", "h": "Muestra el nombre del cliente junto al total de cada pedido.", "r": "Reto mental: La palabra que indica la condición de unión es ___. (2 letras)", "e": "Olvidar la condición ON y unir todas las filas con todas."},
  {"m": "Consultas avanzadas", "t": "INNER JOIN", "x": "Unión que solo devuelve las filas con pareja en ambas tablas.\n\nINNER JOIN (o simplemente JOIN) descarta las filas sin pareja: un cliente sin pedidos no aparece, y un pedido sin cliente tampoco. Es la unión más habitual y suele ser la más rápida.", "u": "Mostrar solo los datos que tienen relación.\n\nQuieres listar únicamente los clientes que sí han hecho pedidos.", "p": ["INNER JOIN devuelve solo las filas con pareja en ambas tablas.", "JOIN solo es lo mismo que INNER JOIN.", "Los clientes sin pedidos no aparecen con INNER JOIN."], "c": "SELECT c.nombre, p.id AS pedido\nFROM clientes c\nINNER JOIN pedidos p ON p.cliente_id = c.id;   -- solo clientes con pedidos", "h": "Lista clientes que tienen al menos un pedido.", "r": "Reto mental: INNER JOIN devuelve solo filas con ___ en ambas tablas. (6 letras: pareja)", "e": "Esperar que INNER JOIN muestre clientes sin pedidos."},
  {"m": "Consultas avanzadas", "t": "LEFT JOIN", "x": "Unión que conserva todas las filas de la tabla izquierda.\n\nLEFT JOIN devuelve todas las filas de la tabla de la izquierda (la que va después de FROM) y, si no hay pareja, rellena con NULL. Para encontrar elementos sin relación se usa LEFT JOIN y luego WHERE derecha.id IS NULL.", "u": "Mostrar también los datos sin pareja, como clientes sin pedidos.\n\nQuieres ver todos los clientes, incluso los que nunca han pedido.", "p": ["LEFT JOIN conserva todas las filas de la tabla izquierda.", "Si no hay pareja, las columnas de la derecha salen NULL.", "Con IS NULL se encuentran las filas sin relación."], "c": "SELECT c.nombre, p.id AS pedido\nFROM clientes c\nLEFT JOIN pedidos p ON p.cliente_id = c.id;       -- todos los clientes\n-- Clientes SIN pedidos:\nSELECT c.nombre FROM clientes c\nLEFT JOIN pedidos p ON p.cliente_id = c.id\nWHERE p.id IS NULL;", "h": "Lista todos los clientes y luego solo los que nunca han hecho un pedido.", "r": "Reto mental: La unión que conserva todas las filas de la tabla izquierda es ___ JOIN. (4 letras)", "e": "Usar INNER JOIN cuando querías conservar todos los clientes."},
  {"m": "Consultas avanzadas", "t": "RIGHT JOIN", "x": "Unión que conserva todas las filas de la tabla derecha.\n\nRIGHT JOIN es el espejo de LEFT JOIN: conserva todas las filas de la tabla de la derecha. Se usa poco, porque casi siempre se puede reescribir con LEFT JOIN cambiando el orden de las tablas, que se lee con más naturalidad.", "u": "Mostrar todos los elementos de la segunda tabla aunque no tengan pareja.\n\nQuieres listar todos los productos de la tabla derecha, incluso los que nunca se han vendido.", "p": ["RIGHT JOIN conserva todas las filas de la tabla derecha.", "Es el espejo de LEFT JOIN.", "Casi siempre se puede reescribir como LEFT JOIN."], "c": "SELECT pr.nombre, d.pedido_id\nFROM detalle_pedido d\nRIGHT JOIN productos pr ON pr.id = d.producto_id;   -- todos los productos\n-- Equivale a: FROM productos pr LEFT JOIN detalle_pedido d ...", "h": "Lista todos los productos aunque nunca se hayan vendido.", "r": "Reto mental: La unión que conserva todas las filas de la tabla derecha es ___ JOIN. (5 letras)", "e": "Confundir cuál es la tabla izquierda y cuál la derecha."},
  {"m": "Consultas avanzadas", "t": "Alias de tablas en JOIN", "x": "Abreviaturas de las tablas para escribir consultas más cortas.\n\nCon FROM clientes AS c escribes c.nombre en vez de clientes.nombre. Es imprescindible cuando unes una tabla consigo misma o cuando dos tablas tienen columnas con el mismo nombre (como id): MySQL no sabría a cuál te refieres.", "u": "Evitar ambigüedad y repetir nombres largos.\n\nDos tablas tienen una columna id y MySQL da error por ambigüedad.", "p": ["Los alias acortan los nombres de tablas en la consulta.", "Se necesitan cuando dos tablas tienen columnas con el mismo nombre.", "Se escriben con AS o directamente tras el nombre."], "c": "SELECT c.id AS cliente, p.id AS pedido, c.nombre\nFROM clientes AS c\nJOIN pedidos  AS p ON p.cliente_id = c.id;   -- c y p evitan el conflicto de «id»", "h": "Distingue dos columnas id con alias de tabla.", "r": "Reto mental: Cuando dos columnas se llaman igual, hay que indicar la ___ de cada una. (5 letras: tabla)", "e": "Escribir id sin indicar de qué tabla es. id existe en las dos tablas: hay que escribir c.id o p.id."},
  {"m": "Consultas avanzadas", "t": "Unir tres tablas", "x": "Consulta que encadena varios JOIN.\n\nCada JOIN añade una tabla a la anterior. Para mostrar qué productos compró cada cliente: clientes JOIN pedidos JOIN detalle JOIN productos. Piensa en el camino que recorren las claves foráneas y escribe un JOIN por cada paso.", "u": "Combinar datos de más de dos tablas.\n\nQuieres mostrar el nombre del cliente, el pedido y el producto comprado, que están en tres tablas.", "p": ["Se pueden encadenar tantos JOIN como se necesite.", "Cada JOIN necesita su propia condición ON.", "Las claves foráneas marcan el camino entre tablas."], "c": "SELECT c.nombre, p.id AS pedido, pr.nombre AS producto\nFROM clientes c\nJOIN pedidos p          ON p.cliente_id  = c.id        -- cliente -> pedido\nJOIN detalle_pedido d   ON d.pedido_id   = p.id        -- pedido  -> detalle\nJOIN productos pr       ON pr.id         = d.producto_id;  -- detalle -> producto", "h": "Une clientes, pedidos, detalles y productos siguiendo las claves.", "r": "Reto mental: Cada JOIN necesita su propia condición ___. (2 letras)", "e": "Olvidar la condición ON de alguna unión."},
  {"m": "Consultas avanzadas", "t": "Subconsulta", "x": "Consulta escrita dentro de otra consulta.\n\nSe escribe entre paréntesis. WHERE nota > (SELECT AVG(nota) FROM alumnos) busca los alumnos por encima de la media. También funciona con IN. Las subconsultas son potentes, pero a veces un JOIN es más claro y rápido.", "u": "Usar el resultado de una consulta como filtro o valor de otra.\n\nQuieres encontrar los alumnos con nota superior a la media de todos.", "p": ["Una subconsulta es una consulta dentro de otra.", "Se escribe entre paréntesis.", "A veces un JOIN es más eficiente que una subconsulta."], "c": "SELECT nombre, nota\nFROM alumnos\nWHERE nota > (SELECT AVG(nota) FROM alumnos);   -- la media se calcula primero\nSELECT nombre FROM alumnos\nWHERE curso IN (SELECT curso FROM cursos_activos);", "h": "Busca alumnos por encima de la media usando una consulta interna.", "r": "Reto mental: Una subconsulta se escribe entre ___. (paréntesis)", "e": "Olvidar los paréntesis de la subconsulta."},
  {"m": "Consultas avanzadas", "t": "EXISTS", "x": "Operador que comprueba si una subconsulta devuelve alguna fila.\n\nWHERE EXISTS (SELECT 1 FROM pedidos WHERE ...) es verdadero si la subconsulta devuelve al menos una fila. Es muy eficiente para saber si hay relación, porque se detiene al encontrar la primera coincidencia. NOT EXISTS busca los que no tienen.", "u": "Preguntar «¿existe alguno?» sin importar cuántos.\n\nQuieres saber qué clientes tienen al menos un pedido, sin importar cuántos.", "p": ["EXISTS es verdadero si la subconsulta devuelve alguna fila.", "NOT EXISTS busca los que no tienen coincidencias.", "EXISTS se detiene al encontrar la primera coincidencia."], "c": "SELECT c.nombre\nFROM clientes c\nWHERE EXISTS (SELECT 1 FROM pedidos p WHERE p.cliente_id = c.id);   -- tiene algún pedido\n-- Los que NO tienen ninguno:\nSELECT c.nombre FROM clientes c\nWHERE NOT EXISTS (SELECT 1 FROM pedidos p WHERE p.cliente_id = c.id);", "h": "Encuentra clientes con pedidos y clientes sin ninguno.", "r": "Reto mental: El operador que pregunta si una subconsulta devuelve filas es ___. (6 letras)", "e": "Usar EXISTS sin relacionar la subconsulta con la consulta externa."},
  {"m": "Consultas avanzadas", "t": "UNION", "x": "Operador que junta los resultados de varias consultas.\n\nUNION une los resultados de dos SELECT con el mismo número de columnas y tipos compatibles, eliminando duplicados. UNION ALL conserva los duplicados y es más rápido. Los nombres de columnas son los del primer SELECT.", "u": "Combinar listas de tablas distintas en un solo resultado.\n\nQuieres una sola lista con los correos de clientes y los de proveedores.", "p": ["UNION une los resultados de varios SELECT.", "Los SELECT deben tener el mismo número de columnas.", "UNION ALL conserva los duplicados."], "c": "SELECT correo FROM clientes\nUNION                          -- elimina repetidos\nSELECT correo FROM proveedores;\n-- UNION ALL los conserva y es más rápido:\nSELECT correo FROM clientes\nUNION ALL\nSELECT correo FROM proveedores;", "h": "Junta los correos de dos tablas con y sin eliminar duplicados.", "r": "Reto mental: El operador que junta resultados de varias consultas es ___. (5 letras)", "e": "Unir consultas con distinto número de columnas."},
  {"m": "Consultas avanzadas", "t": "CASE", "x": "Expresión que elige un resultado según condiciones.\n\nCASE funciona como un «si… entonces… si no…»: WHEN condición THEN valor, y ELSE para el resto. Termina con END. Sirve para convertir notas en «Aprobado» y «Suspenso», o agrupar edades en rangos, sin modificar la tabla.", "u": "Crear categorías o etiquetas dentro de una consulta.\n\nQuieres mostrar «Aprobado» o «Suspenso» según la nota, sin guardar ese texto en la tabla.", "p": ["CASE devuelve un valor según condiciones.", "Termina con END.", "ELSE define el resultado cuando no se cumple ninguna condición."], "c": "SELECT nombre, nota,\n  CASE\n    WHEN nota >= 9 THEN 'Sobresaliente'\n    WHEN nota >= 5 THEN 'Aprobado'\n    ELSE 'Suspenso'                 -- el resto de casos\n  END AS resultado\nFROM alumnos;", "h": "Convierte cada nota en una etiqueta de texto sin modificar la tabla.", "r": "Reto mental: La expresión que elige un resultado según condiciones es ___. (4 letras)", "e": "Olvidar END al final del CASE. Falta cerrar el CASE con END antes de FROM."},
  {"m": "Consultas avanzadas", "t": "Funciones de texto", "x": "Funciones que transforman o miden cadenas de texto.\n\nCONCAT une textos, UPPER y LOWER cambian a mayúsculas o minúsculas, LENGTH cuenta caracteres, TRIM quita espacios sobrantes y SUBSTRING extrae una parte. No cambian los datos guardados: solo el resultado de la consulta.", "u": "Limpiar, unir o cambiar el formato de nombres y textos.\n\nQuieres mostrar nombre y apellido en una sola columna y en mayúsculas.", "p": ["CONCAT une varios textos en uno.", "UPPER convierte a mayúsculas y LOWER a minúsculas.", "TRIM elimina espacios al principio y al final."], "c": "SELECT CONCAT(nombre, ' ', apellido)       AS completo,   -- une textos\n       UPPER(nombre)                        AS en_mayus,   -- MAYÚSCULAS\n       LENGTH(nombre)                       AS letras,     -- cuántos caracteres\n       TRIM('   hola   ')                   AS limpio      -- quita espacios\nFROM alumnos;", "h": "Une, convierte y mide textos sin modificar los datos guardados.", "r": "Reto mental: La función que une varios textos es ___. (6 letras)", "e": "Creer que UPPER cambia el dato guardado en la tabla."},
  {"m": "Consultas avanzadas", "t": "Funciones de fecha", "x": "Funciones que obtienen y calculan con fechas.\n\nNOW() devuelve la fecha y hora actuales, CURDATE() solo la fecha. YEAR, MONTH y DAY extraen partes. DATEDIFF resta dos fechas y DATE_ADD suma días. Con ellas sacas «pedidos del último mes» o «días hasta el vencimiento».", "u": "Saber qué día es, calcular edades o plazos.\n\nQuieres calcular cuántos días han pasado desde cada pedido hasta hoy.", "p": ["NOW() devuelve la fecha y hora actuales.", "DATEDIFF calcula los días entre dos fechas.", "YEAR(), MONTH() y DAY() extraen partes de una fecha."], "c": "SELECT NOW()      AS ahora,                          -- fecha y hora actuales\n       CURDATE()   AS hoy,                            -- solo la fecha\n       YEAR(fecha) AS anio,                           -- extrae el año\n       DATEDIFF(CURDATE(), fecha) AS dias_desde_pedido  -- días transcurridos\nFROM pedidos;", "h": "Obtiene la fecha actual y los días transcurridos desde cada pedido.", "r": "Reto mental: La función que devuelve la fecha y hora actuales es ___(). (3 letras)", "e": "Comparar fechas como si fueran texto."},
  {"m": "Consultas avanzadas", "t": "Vistas", "x": "Consulta guardada con nombre que se usa como una tabla.\n\nCREATE VIEW resumen AS SELECT ... guarda la consulta. Después puedes escribir SELECT * FROM resumen como si fuera una tabla. La vista no guarda datos: ejecuta la consulta cada vez. Ayuda a ocultar columnas sensibles a ciertos usuarios.", "u": "Reutilizar consultas complejas y simplificar permisos.\n\nQuieres guardar una consulta compleja con JOIN para reutilizarla como si fuera una tabla.", "p": ["Una vista es una consulta guardada con nombre.", "Una vista no guarda datos propios.", "Las vistas pueden ocultar columnas sensibles."], "c": "CREATE VIEW ventas_por_cliente AS\nSELECT c.nombre, SUM(p.total) AS comprado\nFROM clientes c JOIN pedidos p ON p.cliente_id = c.id\nGROUP BY c.nombre;\nSELECT * FROM ventas_por_cliente WHERE comprado > 100;   -- se usa como una tabla", "h": "Guarda una consulta con JOIN y agrupación y la consulta como una tabla.", "r": "Reto mental: El comando que guarda una consulta con nombre es CREATE ___. (4 letras)", "e": "Creer que la vista copia los datos."},
  {"m": "Consultas avanzadas", "t": "COALESCE e IFNULL", "x": "Funciones que sustituyen los valores NULL por otro valor.\n\nIFNULL(telefono, 'Sin teléfono') devuelve el teléfono o el texto si es NULL. COALESCE acepta varios valores y devuelve el primero que no sea NULL. Evitan que los NULL rompan cálculos y presenten celdas vacías.", "u": "Mostrar un texto o número por defecto cuando falta un dato.\n\nQuieres mostrar «Sin teléfono» cuando un cliente no tiene teléfono registrado.", "p": ["IFNULL sustituye un NULL por otro valor.", "COALESCE devuelve el primer valor que no sea NULL.", "Los NULL pueden romper cálculos si no se sustituyen."], "c": "SELECT nombre,\n       IFNULL(telefono, 'Sin teléfono')               AS tel,      -- reemplaza NULL\n       COALESCE(movil, telefono, 'No indicado')       AS contacto  -- primer valor no nulo\nFROM clientes;", "h": "Reemplaza datos ausentes por textos claros en el resultado.", "r": "Reto mental: La función que devuelve el primer valor no nulo es ___. (8 letras)", "e": "Sumar columnas con NULL sin sustituirlos."},
  {"m": "Rendimiento y práctica profesional", "t": "Índices", "x": "Estructura que acelera las búsquedas en una columna.\n\nUn índice funciona como el índice de un libro: en vez de leer todas las páginas, vas directo a la que buscas. Se crean sobre las columnas que más se usan en WHERE, JOIN y ORDER BY. Aceleran las lecturas, pero ralentizan un poco las escrituras y ocupan espacio.", "u": "Encontrar filas rápido sin recorrer toda la tabla.\n\nUna consulta por correo tarda segundos en una tabla con millones de filas.", "p": ["Un índice acelera las búsquedas por una columna.", "Los índices ralentizan un poco los INSERT y UPDATE.", "Se crean en columnas usadas en WHERE, JOIN y ORDER BY."], "c": "CREATE INDEX idx_usuarios_correo ON usuarios (correo);   -- índice sobre el correo\nSELECT * FROM usuarios WHERE correo = 'ana@correo.com';  -- ahora busca rápido\n-- Sin índice, MySQL recorre TODAS las filas", "h": "Crea un índice para acelerar las búsquedas por correo.", "r": "Reto mental: El comando que crea un índice es CREATE ___. (5 letras)", "e": "Crear índices en todas las columnas sin necesidad."},
  {"m": "Rendimiento y práctica profesional", "t": "Índices compuestos", "x": "Índice que abarca varias columnas a la vez.\n\nUn índice sobre (apellido, nombre) ayuda cuando buscas por apellido, o por apellido y nombre, pero no cuando buscas solo por nombre. El orden de las columnas importa: pon primero la que más se filtra. Un índice UNIQUE compuesto además impide repetir la combinación.", "u": "Acelerar consultas que filtran por más de una columna.\n\nBuscas con frecuencia por apellido y nombre a la vez.", "p": ["Un índice compuesto abarca varias columnas.", "El orden de las columnas en el índice importa.", "Un UNIQUE compuesto impide repetir la combinación."], "c": "CREATE INDEX idx_alumno_nombre ON alumnos (apellido, nombre);   -- compuesto\n-- Ayuda a:  WHERE apellido = 'Pérez'\n-- Ayuda a:  WHERE apellido = 'Pérez' AND nombre = 'Ana'\n-- NO ayuda: WHERE nombre = 'Ana'   (la primera columna es apellido)", "h": "Crea un índice sobre dos columnas y explica cuándo se aprovecha.", "r": "Reto mental: En un índice compuesto, el ___ de las columnas importa. (5 letras)", "e": "Poner primero en el índice la columna menos usada."},
  {"m": "Rendimiento y práctica profesional", "t": "EXPLAIN", "x": "Comando que muestra cómo ejecutará MySQL una consulta.\n\nSi escribes EXPLAIN antes de un SELECT, MySQL no ejecuta la consulta, sino que muestra su plan: qué índice usa y cuántas filas piensa revisar. Si ves type = ALL, recorre toda la tabla; es la señal de que quizás falta un índice.", "u": "Descubrir por qué una consulta es lenta.\n\nQuieres saber si una consulta lenta está usando algún índice.", "p": ["EXPLAIN muestra el plan de ejecución de una consulta.", "El tipo ALL indica que se recorre toda la tabla.", "Sirve para decidir qué índices crear."], "c": "EXPLAIN SELECT * FROM usuarios WHERE correo = 'ana@correo.com';\n-- type = ALL   -> recorre toda la tabla (lento)\n-- type = ref   -> usa un índice (rápido)\n-- key          -> índice elegido; rows -> filas estimadas", "h": "Pide el plan de una consulta y explica cómo interpretarlo.", "r": "Reto mental: La palabra que muestra el plan de una consulta es ___. (7 letras)", "e": "Optimizar consultas sin medirlas antes."},
  {"m": "Rendimiento y práctica profesional", "t": "Transacciones", "x": "Grupo de operaciones que se ejecutan como una sola unidad.\n\nUna transferencia bancaria resta dinero a una cuenta y lo suma a otra. Si falla en medio, no puede quedar la mitad hecha. Una transacción agrupa ambas operaciones: o se hacen todas o no se hace ninguna.", "u": "Evitar datos a medias si algo falla.\n\nUna transferencia debe restar a una cuenta y sumar a otra, o no hacerse en absoluto.", "p": ["Una transacción agrupa varias operaciones en una unidad.", "O se ejecutan todas las operaciones o ninguna.", "Evitan datos a medias cuando algo falla."], "c": "START TRANSACTION;                                        -- empieza la unidad\nUPDATE cuentas SET saldo = saldo - 100 WHERE id = 1;     -- resta\nUPDATE cuentas SET saldo = saldo + 100 WHERE id = 2;     -- suma\nCOMMIT;                                                  -- confirma las dos", "h": "Agrupa una resta y una suma de saldo en una única unidad.", "r": "Reto mental: Una transacción comienza con START ___. (11 letras)", "e": "Hacer operaciones relacionadas por separado y dejar datos a medias."},
  {"m": "Rendimiento y práctica profesional", "t": "COMMIT y ROLLBACK", "x": "Comandos que confirman o deshacen una transacción.\n\nCOMMIT guarda definitivamente todos los cambios de la transacción. ROLLBACK los deshace y deja la base como estaba al empezar. Tras un error en la aplicación, se hace ROLLBACK para no dejar cambios a medias.", "u": "Decidir si los cambios se guardan o se descartan.\n\nAlgo falló a mitad de una transacción y quieres deshacer todo lo hecho.", "p": ["COMMIT confirma definitivamente los cambios.", "ROLLBACK deshace los cambios de la transacción.", "Tras un error conviene hacer ROLLBACK."], "c": "START TRANSACTION;\nDELETE FROM pedidos WHERE cliente_id = 7;\n-- ¡Me equivoqué de cliente!\nROLLBACK;                    -- todo vuelve a como estaba\n-- Si hubiera sido correcto: COMMIT;", "h": "Deshace un borrado hecho por error dentro de una transacción.", "r": "Reto mental: El comando que deshace una transacción es ___. (8 letras)", "e": "Olvidar COMMIT y creer que los cambios ya se guardaron."},
  {"m": "Rendimiento y práctica profesional", "t": "ACID", "x": "Cuatro garantías de las transacciones fiables.\n\nACID son las siglas de Atomicidad (todo o nada), Consistencia (se cumplen las reglas), Aislamiento (las transacciones simultáneas no se estorban) y Durabilidad (lo confirmado no se pierde ni con un apagón). MySQL con InnoDB las cumple.", "u": "Confiar en que los datos quedan correctos aunque haya fallos.\n\nQuieres describir las cuatro garantías que hacen fiables a las transacciones.", "p": ["ACID significa Atomicidad, Consistencia, Aislamiento y Durabilidad.", "La atomicidad significa todo o nada.", "La durabilidad garantiza que lo confirmado no se pierde."], "c": "-- A: Atomicidad    -> todo o nada\n-- C: Consistencia  -> siempre se cumplen las reglas\n-- I: Aislamiento   -- transacciones simultáneas no se estorban\n-- D: Durabilidad   -> lo confirmado no se pierde\nSELECT 'InnoDB cumple ACID' AS motor;", "h": "Resume las cuatro garantías ACID de las transacciones.", "r": "Reto mental: La A de ACID significa ___. (10 letras: atomicidad)", "e": "Confundir consistencia con aislamiento."},
  {"m": "Rendimiento y práctica profesional", "t": "Concurrencia y bloqueos", "x": "Situación en que varios usuarios usan los mismos datos a la vez.\n\nSi dos personas compran la última entrada a la vez, sin control se venderían dos. La base de datos usa bloqueos: mientras una transacción modifica una fila, la otra espera. SELECT ... FOR UPDATE bloquea las filas leídas hasta terminar. Los bloqueos largos o cruzados pueden causar interbloqueos.", "u": "Evitar que dos usuarios se pisen al modificar lo mismo.\n\nDos usuarios intentan comprar la última entrada a la vez.", "p": ["Los bloqueos impiden que dos transacciones modifiquen lo mismo a la vez.", "SELECT ... FOR UPDATE bloquea las filas leídas.", "Un interbloqueo ocurre cuando dos transacciones se esperan mutuamente."], "c": "START TRANSACTION;\nSELECT stock FROM entradas WHERE id = 1 FOR UPDATE;   -- bloquea la fila\nUPDATE entradas SET stock = stock - 1 WHERE id = 1;   -- nadie más la toca\nCOMMIT;                                               -- libera el bloqueo", "h": "Bloquea la fila mientras se reserva la última entrada.", "r": "Reto mental: Cuando dos transacciones se esperan mutuamente ocurre un ___. (13 letras)", "e": "Mantener transacciones abiertas demasiado tiempo."},
  {"m": "Rendimiento y práctica profesional", "t": "Usuarios y permisos", "x": "Cuentas de la base de datos con derechos limitados.\n\nCREATE USER crea una cuenta y GRANT le da permisos concretos sobre bases o tablas: SELECT, INSERT, UPDATE, DELETE. Cada aplicación debe tener su propio usuario con solo lo imprescindible, nunca el administrador.", "u": "Controlar quién puede leer, escribir o administrar.\n\nQuieres que el usuario de la web solo pueda leer y escribir en la base de la tienda.", "p": ["GRANT concede permisos a un usuario.", "Cada aplicación debería tener su propio usuario.", "La aplicación no debe usar la cuenta administradora."], "c": "CREATE USER 'web'@'localhost' IDENTIFIED BY 'clave-larga-y-unica';\nGRANT SELECT, INSERT, UPDATE ON tienda.* TO 'web'@'localhost';\n-- Sin DELETE ni DROP: si la app es atacada, el daño es menor\nSHOW GRANTS FOR 'web'@'localhost';", "h": "Crea un usuario web con permisos limitados y los consulta.", "r": "Reto mental: El comando que concede permisos es ___. (5 letras)", "e": "Usar root en la aplicación."},
  {"m": "Rendimiento y práctica profesional", "t": "Inyección SQL", "x": "Ataque que introduce código SQL malicioso en un campo.\n\nSi construyes la consulta pegando texto del usuario, alguien puede escribir ' OR '1'='1 y entrar sin contraseña, o ; DROP TABLE usuarios; y borrar datos. Nunca se concatena la entrada del usuario dentro del SQL: se usan consultas preparadas.", "u": "Entender uno de los ataques más peligrosos y evitarlo.\n\nAlguien escribe ' OR '1'='1 en el campo de contraseña y entra sin conocerla.", "p": ["La inyección SQL introduce comandos maliciosos por un campo del usuario.", "Nunca se debe concatenar texto del usuario dentro de una consulta.", "Se evita con consultas preparadas."], "c": "-- MAL: la consulta se construye pegando texto del usuario\n-- \"SELECT * FROM usuarios WHERE correo = '\" + correo + \"' AND clave = '\" + clave + \"'\"\n-- Si clave = ' OR '1'='1  la condición siempre es verdadera:\nSELECT * FROM usuarios WHERE correo = 'x' AND clave = '' OR '1'='1';", "h": "Muestra cómo un texto malicioso hace que la condición siempre sea verdadera.", "r": "Reto mental: El ataque que mete código SQL por un campo se llama inyección ___. (3 letras)", "e": "Pegar directamente en el SQL el texto que escribe el usuario."},
  {"m": "Rendimiento y práctica profesional", "t": "Consultas preparadas", "x": "Consultas con marcadores que separan el SQL de los datos.\n\nSe escribe la consulta con marcadores (? o :nombre) y los valores se envían aparte. La base de datos trata esos valores siempre como datos, nunca como SQL. Las librerías de cada lenguaje (PDO, mysql2, SQLAlchemy) lo hacen fácil.", "u": "Evitar la inyección SQL y reutilizar consultas.\n\nQuieres que lo que escribe el usuario nunca se interprete como código SQL.", "p": ["Las consultas preparadas separan el SQL de los datos.", "Los valores se envían aparte con marcadores.", "Son la defensa principal contra la inyección SQL."], "c": "-- La consulta lleva marcadores ? y los valores viajan aparte\nPREPARE buscar FROM 'SELECT * FROM usuarios WHERE correo = ? AND activo = ?';\nSET @c = 'ana@correo.com', @a = 1;\nEXECUTE buscar USING @c, @a;       -- @c nunca se interpreta como SQL", "h": "Separa la consulta de sus valores usando marcadores.", "r": "Reto mental: En una consulta preparada, los valores se sustituyen por marcadores como el signo ___. (un carácter)", "e": "Creer que escapar comillas a mano es suficiente."},
  {"m": "Rendimiento y práctica profesional", "t": "Contraseñas con hash", "x": "Forma de guardar contraseñas transformadas e irreversibles.\n\nNunca se guarda la contraseña en texto plano. Se guarda su hash, calculado con un algoritmo lento y seguro como bcrypt o Argon2, junto con una sal aleatoria. Para comprobar un inicio de sesión se calcula el hash de lo escrito y se compara con el guardado.", "u": "Que una filtración no revele las contraseñas reales.\n\nQuieres que, aunque roben tu base de datos, no se vean las contraseñas reales.", "p": ["Las contraseñas se guardan como hash, no en texto plano.", "bcrypt y Argon2 son algoritmos recomendados para contraseñas.", "Para validar se compara el hash, no la contraseña original."], "c": "CREATE TABLE usuarios (\n  id INT PRIMARY KEY AUTO_INCREMENT,\n  correo VARCHAR(80) UNIQUE NOT NULL,\n  clave_hash VARCHAR(255) NOT NULL    -- aquí va el hash, nunca la clave real\n);\n-- Ejemplo ilustrativo de lo que se guarda (bcrypt):\n-- $2b$12$KIXQe6q7mN... (60 caracteres)", "h": "Reserva una columna para el hash de la contraseña en lugar de la clave real.", "r": "Reto mental: Las contraseñas se guardan como ___, no en texto plano. (4 letras)", "e": "Guardar las contraseñas en texto plano. Nunca se guarda la contraseña en texto plano: se debe guardar un hash."},
  {"m": "Rendimiento y práctica profesional", "t": "Importar y exportar datos", "x": "Mover datos hacia y desde la base mediante archivos.\n\nCon LOAD DATA INFILE o el asistente de Workbench importas un CSV a una tabla. Con SELECT ... INTO OUTFILE o mysqldump exportas. El formato CSV lo abre cualquier hoja de cálculo. Revisa la codificación (UTF-8) y valida los datos antes de importarlos.", "u": "Cargar datos masivos o llevarlos a otras herramientas.\n\nTienes 5000 alumnos en un archivo CSV y quieres cargarlos en una tabla.", "p": ["Los archivos CSV permiten mover datos entre herramientas.", "mysqldump exporta una base completa.", "Conviene revisar la codificación UTF-8 al importar."], "c": "LOAD DATA LOCAL INFILE 'alumnos.csv'\nINTO TABLE alumnos\nFIELDS TERMINATED BY ','            -- columnas separadas por coma\nLINES TERMINATED BY '\\n'\nIGNORE 1 LINES                       -- salta la fila de títulos\n(nombre, curso, nota);", "h": "Carga un archivo CSV en una tabla saltando la fila de títulos.", "r": "Reto mental: Un archivo de datos separados por comas es un ___. (3 letras)", "e": "Importar datos sin revisarlos antes."},
  {"m": "Rendimiento y práctica profesional", "t": "Procedimientos almacenados", "x": "Bloques de SQL guardados en la base que se ejecutan por nombre.\n\nUn procedimiento se crea con CREATE PROCEDURE, recibe parámetros y se lanza con CALL. Es útil para operaciones repetidas o con varios pasos. A cambio, la lógica queda dentro de la base y es más difícil de versionar que el código de la aplicación.", "u": "Reutilizar lógica y reducir viajes entre aplicación y base.\n\nQuieres guardar en la base unos pasos repetidos para ejecutarlos con una sola llamada.", "p": ["Un procedimiento almacenado se ejecuta con CALL.", "Puede recibir parámetros.", "La lógica queda guardada dentro de la base de datos."], "c": "DELIMITER //\nCREATE PROCEDURE subir_nota(IN p_id INT, IN p_extra DECIMAL(4,2))\nBEGIN\n  UPDATE alumnos SET nota = LEAST(10, nota + p_extra) WHERE id = p_id;\nEND //\nDELIMITER ;\nCALL subir_nota(3, 0.5);     -- se ejecuta por su nombre", "h": "Guarda una operación con parámetros y la ejecuta con CALL.", "r": "Reto mental: El comando que ejecuta un procedimiento almacenado es ___. (4 letras)", "e": "Esconder demasiada lógica del negocio dentro de la base."},
  {"m": "Rendimiento y práctica profesional", "t": "Triggers", "x": "Código que se ejecuta automáticamente ante un cambio en una tabla.\n\nUn trigger se asocia a una tabla y a un evento (INSERT, UPDATE o DELETE), antes o después. Por ejemplo, guardar en una tabla de historial cada vez que cambia el precio de un producto. Úsalos con moderación: los efectos ocultos son difíciles de depurar.", "u": "Automatizar acciones como registrar auditorías.\n\nQuieres que cada vez que cambie el precio de un producto quede registrado automáticamente.", "p": ["Un trigger se ejecuta solo cuando ocurre un evento en la tabla.", "Puede ejecutarse antes o después del evento.", "Los triggers ocultos pueden dificultar la depuración."], "c": "CREATE TRIGGER guardar_historial\nAFTER UPDATE ON productos\nFOR EACH ROW\n  INSERT INTO historial_precios (producto_id, precio_anterior, cambiado)\n  VALUES (OLD.id, OLD.precio, NOW());   -- OLD: valores antes del cambio", "h": "Registra automáticamente el precio anterior cada vez que cambia.", "r": "Reto mental: El código que se ejecuta automáticamente ante un cambio se llama ___. (7 letras)", "e": "Llenar la base de triggers que nadie recuerda."},
  {"m": "Rendimiento y práctica profesional", "t": "Borrado en cascada", "x": "Regla que decide qué pasa con los hijos al borrar un padre.\n\nCon ON DELETE CASCADE, al borrar un cliente se borran también sus pedidos. Con ON DELETE SET NULL, los pedidos quedan sin cliente. Con RESTRICT (por defecto) no te deja borrar al cliente mientras tenga pedidos. Elige según el significado del negocio.", "u": "Evitar datos huérfanos al borrar registros relacionados.\n\nQuieres que, al borrar un cliente, desaparezcan también todos sus pedidos.", "p": ["ON DELETE CASCADE borra también los registros hijos.", "ON DELETE SET NULL deja la clave foránea vacía.", "RESTRICT impide borrar un padre con hijos."], "c": "CREATE TABLE pedidos (\n  id INT PRIMARY KEY,\n  cliente_id INT,\n  FOREIGN KEY (cliente_id) REFERENCES clientes(id)\n    ON DELETE CASCADE          -- borra también los pedidos del cliente\n);\nDELETE FROM clientes WHERE id = 3;   -- sus pedidos se eliminan solos", "h": "Borra los pedidos automáticamente cuando se borra su cliente.", "r": "Reto mental: La regla que borra también los registros hijos es ON DELETE ___. (7 letras)", "e": "Usar CASCADE sin pensar qué datos se perderán."},
  {"m": "Rendimiento y práctica profesional", "t": "Borrado lógico", "x": "Técnica de marcar un registro como eliminado sin borrarlo.\n\nEn lugar de DELETE, se añade una columna como eliminado o borrado_en y se marca. Las consultas habituales filtran WHERE eliminado = 0. Permite deshacer errores y mantener el historial, a costa de tener que recordar el filtro siempre.", "u": "Poder recuperar datos y conservar el historial.\n\nQuieres «borrar» un usuario pero poder recuperarlo después si se arrepiente.", "p": ["El borrado lógico marca el registro sin eliminarlo.", "Permite recuperar datos borrados por error.", "Las consultas deben filtrar los registros marcados."], "c": "ALTER TABLE usuarios ADD eliminado BOOLEAN DEFAULT FALSE;\nUPDATE usuarios SET eliminado = TRUE WHERE id = 9;     -- «borrado» lógico\nSELECT * FROM usuarios WHERE eliminado = FALSE;        -- el resto de consultas lo filtran", "h": "Marca a un usuario como eliminado sin borrar sus datos.", "r": "Reto mental: En el borrado ___, los datos se marcan pero no se eliminan. (6 letras)", "e": "Olvidar filtrar los registros eliminados en las consultas."},
  {"m": "Rendimiento y práctica profesional", "t": "Optimizar consultas", "x": "Conjunto de buenas prácticas para que las consultas sean rápidas.\n\nPide solo las columnas necesarias, filtra con WHERE, usa índices en columnas de búsqueda, evita funciones sobre columnas indexadas en el WHERE y limita resultados con LIMIT. Mide con EXPLAIN antes y después. Optimiza solo lo que de verdad es lento.", "u": "Mantener la aplicación ágil cuando crecen los datos.\n\nTu consulta tarda 5 segundos y quieres que sea rápida con buenas prácticas.", "p": ["Conviene pedir solo las columnas y filas necesarias.", "Los índices aceleran las columnas que se buscan.", "Hay que medir con EXPLAIN antes y después de optimizar."], "c": "-- Lento: trae todo y aplica una función a la columna indexada\nSELECT * FROM pedidos WHERE YEAR(fecha) = 2026;\n-- Rápido: columnas necesarias y condición que usa el índice\nSELECT id, total FROM pedidos\nWHERE fecha >= '2026-01-01' AND fecha < '2027-01-01';", "h": "Reescribe una consulta lenta para que aproveche el índice de fecha.", "r": "Reto mental: Para ver el plan de una consulta antes de optimizarla se usa ___. (7 letras)", "e": "Optimizar a ciegas sin medir."},
  {"m": "Rendimiento y práctica profesional", "t": "Elegir una base de datos", "x": "Criterio para decidir qué tipo de base usar en un proyecto.\n\nPara datos con relaciones claras y transacciones, una base relacional (MySQL, PostgreSQL). Para documentos flexibles, MongoDB. Para caché y datos temporales muy rápidos, Redis. Para pocos datos en una app pequeña, SQLite. Empieza simple y cambia solo si lo necesitas.", "u": "No usar una herramienta equivocada para el problema.\n\nVas a crear una tienda con clientes, pedidos y pagos que necesitan transacciones seguras.", "p": ["Las bases relacionales sirven para datos con relaciones y transacciones.", "Redis es ideal para caché y datos temporales.", "SQLite es adecuada para proyectos pequeños."], "c": "-- Guía rápida (en comentarios):\n-- Tienda, banco, escuela ............ relacional: MySQL o PostgreSQL\n-- Perfiles con campos cambiantes .... documental: MongoDB\n-- Caché, sesiones, contadores ....... clave-valor: Redis\n-- App móvil pequeña sin servidor .... SQLite\nSELECT 'empieza simple' AS consejo;", "h": "Recomienda un tipo de base de datos según el proyecto.", "r": "Reto mental: Para una tienda con transacciones seguras conviene una base ___. (10 letras)", "e": "Elegir una base solo porque está de moda."},
  {"m": "Rendimiento y práctica profesional", "t": "Migraciones de esquema", "x": "Cambios de estructura guardados en archivos versionados.\n\nEn vez de modificar las tablas a mano, cada cambio (añadir una columna, crear una tabla) se escribe en un archivo numerado: 001_crear_clientes.sql, 002_añadir_telefono.sql. Así todo el equipo y todos los servidores aplican los mismos cambios en el mismo orden, y puedes ver el historial en Git.", "u": "Actualizar la base de datos de forma ordenada y repetible.\n\nQuieres que todo el equipo aplique los mismos cambios de estructura en el mismo orden.", "p": ["Una migración es un cambio de estructura guardado en un archivo.", "Las migraciones se aplican siempre en el mismo orden.", "Permiten que todos los entornos tengan la misma estructura."], "c": "-- Archivo 001_crear_clientes.sql\nCREATE TABLE clientes (id INT PRIMARY KEY AUTO_INCREMENT, nombre VARCHAR(50));\n-- Archivo 002_añadir_telefono.sql\nALTER TABLE clientes ADD telefono VARCHAR(15);\n-- Cada archivo se ejecuta una sola vez y en orden", "h": "Describe dos cambios de estructura guardados en archivos numerados.", "r": "Reto mental: Los archivos de migración se aplican siempre en el mismo ___. (5 letras)", "e": "Modificar la estructura a mano en producción sin dejar registro."},
  {"m": "Rendimiento y práctica profesional", "t": "Proyecto base de una tienda", "x": "Diseño completo de una base de datos para una tienda en línea.\n\nPara cerrar el curso, diseña la base de una tienda: clientes, productos, pedidos y detalle de pedido. Dibuja el diagrama, crea las tablas con sus claves y restricciones, inserta datos de prueba y responde preguntas con consultas: ventas por mes, clientes sin pedidos, productos más vendidos.", "u": "Practicar todo lo aprendido en un caso real.\n\nQuieres cerrar el curso diseñando una base completa para una tienda en línea.", "p": ["Un proyecto completo parte de un diagrama y termina con consultas.", "Una tienda necesita clientes, productos, pedidos y detalle de pedido.", "Los datos de prueba permiten comprobar que las consultas funcionan."], "c": "CREATE TABLE clientes  (id INT PRIMARY KEY AUTO_INCREMENT, nombre VARCHAR(50) NOT NULL, correo VARCHAR(80) UNIQUE);\nCREATE TABLE productos (id INT PRIMARY KEY AUTO_INCREMENT, nombre VARCHAR(50), precio DECIMAL(8,2));\nCREATE TABLE pedidos   (id INT PRIMARY KEY AUTO_INCREMENT, cliente_id INT, fecha DATE,\n                        FOREIGN KEY (cliente_id) REFERENCES clientes(id));\nCREATE TABLE detalle   (pedido_id INT, producto_id INT, cantidad INT,\n                        PRIMARY KEY (pedido_id, producto_id));\n-- Pregunta: ¿cuánto vendió cada producto?\nSELECT p.nombre, SUM(d.cantidad) AS vendidas\nFROM detalle d JOIN productos p ON p.id = d.producto_id\nGROUP BY p.nombre ORDER BY vendidas DESC;", "h": "Crea las cuatro tablas de una tienda y consulta cuánto vendió cada producto.", "r": "Reto mental: Para cerrar el curso conviene hacer un ___ completo. (8 letras)", "e": "Empezar a crear tablas sin diseñar antes."}
];
